/**
 * Global scene-state controller — orchestrates day/night + weather
 * effects across the viewer's panorama renderer.
 *
 * Pure orchestration: takes a `DayNightController` + a `RainEmitter`
 * (both pure-logic from `@nova/fx`) and applies the resulting frame
 * to renderer hooks the viewer adapter provides:
 *
 *   - `applyEnvironment(intensity, fogRgb, skyTopRgb, skyHorizonRgb)`
 *     — viewer adapter sets `scene.environment` exposure + `scene.fog`
 *     + sky gradient material.
 *   - `applySunDirection(dir)` — viewer adapter rotates the
 *     directional light + (optionally) the lens-flare anchor.
 *   - `setRainActive(active)` — adapter spawns/disposes the
 *     instanced-mesh raindrop pool.
 *
 * Capabilities gate which sub-systems are active. If `effects.dayNight`
 * is false, the controller never calls `applyEnvironment` / `applySun`
 * regardless of state — the panorama stays at its baked lighting.
 */

import { DayNightController, RainEmitter } from '@nova/fx';

import type { TenantInteractionCapabilities } from '@nova/digital-twin';
import type { Vec3 } from '@nova/fx';

export interface SceneStateHooks {
  /** Optional — only invoked when day/night capability is on. */
  applyEnvironment?: (args: {
    intensity: number;
    fogRgb: readonly [number, number, number];
    skyTopRgb: readonly [number, number, number];
    skyHorizonRgb: readonly [number, number, number];
    starsOpacity: number;
  }) => void;
  applySunDirection?: (dir: readonly [number, number, number]) => void;
  /** Optional — only invoked when weather capability is on. */
  setRainActive?: (active: boolean) => void;
  /** Notified when phase changes (drives the bottom-bar chip text). */
  onPhaseChange?: (phase: 'night' | 'dawn' | 'day' | 'dusk') => void;
}

export interface SceneStateControllerArgs {
  readonly capabilities: TenantInteractionCapabilities;
  readonly hooks: SceneStateHooks;
  readonly cameraPosition?: Vec3;
}

export class SceneStateController {
  private readonly dayNight = new DayNightController();
  private rain: RainEmitter | null = null;
  private rainActive = false;
  private caps: TenantInteractionCapabilities;
  private readonly hooks: SceneStateHooks;
  private cameraPosition: Vec3;
  private lastPhase: 'night' | 'dawn' | 'day' | 'dusk' | null = null;

  constructor(args: SceneStateControllerArgs) {
    this.caps = args.capabilities;
    this.hooks = args.hooks;
    this.cameraPosition = args.cameraPosition ?? [0, 0, 0];
    this.applyCurrentFrame();
  }

  setCapabilities(caps: TenantInteractionCapabilities): void {
    this.caps = caps;
    // If day/night turned off mid-session, reset the renderer to neutral
    // (so the panorama goes back to its baked lighting).
    if (!this.caps.effects?.dayNight) {
      this.hooks.applyEnvironment?.({
        intensity: 1.0,
        fogRgb: [0.5, 0.55, 0.6],
        skyTopRgb: [0.4, 0.6, 0.95],
        skyHorizonRgb: [0.75, 0.85, 0.95],
        starsOpacity: 0,
      });
      this.hooks.applySunDirection?.([0, 1, 0]);
    }
    if (!this.caps.effects?.weather && this.rainActive) {
      this.setRain(false);
    }
    this.applyCurrentFrame();
  }

  /** Tick from the viewer's RAF loop. dtMs in milliseconds. */
  tick(dtMs: number): void {
    if (this.caps.effects?.dayNight) {
      this.dayNight.tick(dtMs);
      this.applyCurrentFrame();
    }
  }

  /** Visitor toggles day ↔ night via the bottom chip. */
  toggleDayNight(): void {
    if (!this.caps.effects?.dayNight) return;
    this.dayNight.toggleDayNight();
    this.applyCurrentFrame();
  }

  /** Visitor opens an explicit phase picker chip (dawn/day/dusk/night). */
  setPhase(phase: 'night' | 'dawn' | 'day' | 'dusk'): void {
    if (!this.caps.effects?.dayNight) return;
    this.dayNight.setPhase(phase);
    this.applyCurrentFrame();
  }

  /** Visitor toggles rain on/off. */
  toggleRain(seed = 1): void {
    if (!this.caps.effects?.weather) return;
    this.setRain(!this.rainActive, seed);
  }

  /** Current phase — used by the chip renderer. */
  currentPhase(): 'night' | 'dawn' | 'day' | 'dusk' {
    return this.dayNight.frame().phase;
  }

  /** Is rain currently raining? */
  isRaining(): boolean {
    return this.rainActive;
  }

  /** Update the camera position the rain emitter spawns above. */
  updateCameraPosition(p: Vec3): void {
    this.cameraPosition = p;
    if (this.rain) this.rain.setCameraPosition(p);
  }

  private applyCurrentFrame(): void {
    if (!this.caps.effects?.dayNight) return;
    const f = this.dayNight.frame();
    this.hooks.applyEnvironment?.({
      intensity: f.envIntensity,
      fogRgb: f.fogRgb,
      skyTopRgb: f.skyTopRgb,
      skyHorizonRgb: f.skyHorizonRgb,
      starsOpacity: f.starsOpacity,
    });
    this.hooks.applySunDirection?.(f.sunDir);
    if (f.phase !== this.lastPhase) {
      this.lastPhase = f.phase;
      this.hooks.onPhaseChange?.(f.phase);
    }
  }

  private setRain(on: boolean, seed = 1): void {
    if (on === this.rainActive) return;
    if (on) {
      this.rain = new RainEmitter('global-rain', {
        cameraPosition: this.cameraPosition,
        ratePerSec: 240,
        spawnWidthM: 8,
        spawnHeightAboveM: 4,
        fallSpeedMs: 7,
        lifeS: 1.4,
        seed,
      });
    } else {
      this.rain?.stop();
      this.rain = null;
    }
    this.rainActive = on;
    this.hooks.setRainActive?.(on);
  }
}
