/**
 * Per-POI-type payload shapes mirrored from `@nova/tours/lib/poi-types.ts`.
 *
 * The viewer trusts the renderer-side type tags because tour-svc validates
 * the payload at insert time against the same Zod schemas — but the viewer
 * still defensively narrows + falls back to a "Type not yet supported"
 * placeholder card when a tour stored under an unknown / future POI code is
 * served to an older viewer build.
 */

import type { Position } from '@nova/tours';

export type PoiTypeCode =
  | 'POI-01'
  | 'POI-02'
  | 'POI-03'
  | 'POI-04'
  | 'POI-05'
  | 'POI-06'
  | 'POI-07'
  | 'POI-08'
  | 'POI-09'
  | 'POI-10'
  | 'POI-11'
  | 'POI-12'
  | 'POI-13'
  | 'POI-14'
  | 'POI-15'
  | 'POI-16';

export interface ViewerPoi {
  id: string;
  typeCode: PoiTypeCode;
  position: Position;
  payload: Record<string, unknown>;
  zIndex?: number;
}

