/**
 * Tour scene graph — pure data model for navigation between panorama scenes.
 *
 * Implements F-10 (hotspot teleport between scenes), F-11 (click-anywhere depth nav),
 * F-15 (minimap with N scenes), F-17 (scene variants — same scene, different conditions
 * e.g. day/night, summer/winter, before/after).
 *
 * Pure data + pure helpers only — no DOM, no Three.js, no I/O. The runtime
 * (SceneNavigator) consumes this model and the viewer app wires the renderer.
 */

export type HotspotKind =
  /** Standard doorway / portal between scenes — rendered with an arrow icon. */
  | 'doorway'
  /** Floor-pad depth-nav target — F-11 click-anywhere. Renders as a flat ring on the ground. */
  | 'floor'
  /** Generic teleport (e.g., "back to lobby" shortcut on the side of a corridor). */
  | 'teleport';

export type SceneTransitionKind = 'instant' | 'fade' | 'dolly';

export interface SceneHotspot {
  id: string;
  toSceneId: string;
  /** Yaw in degrees, 0..360. Anchors where the hotspot icon paints in the current panorama. */
  yawDeg: number;
  /** Pitch in degrees, -90..90. */
  pitchDeg: number;
  /** Optional override of the destination yaw on arrival. If undefined, lands at scene default. */
  arriveYawDeg?: number;
  /** Optional override of the destination pitch on arrival. */
  arrivePitchDeg?: number;
  kind: HotspotKind;
  label: string;
  /** Optional accessible description for screen-reader users (long-form). */
  description?: string;
  transition?: SceneTransitionKind;
}

export interface SceneVariant {
  id: string;
  label: string;
  panoramaUrl: string;
  /** Optional thumbnail to show in the variant picker. */
  thumbnailUrl?: string;
  /** Optional default camera override when entering this variant. */
  defaultYawDeg?: number;
  defaultPitchDeg?: number;
}

export interface MinimapAnchor {
  /** Normalised X coordinate in the floor plan, 0..1 (left → right). */
  x: number;
  /** Normalised Y coordinate in the floor plan, 0..1 (top → bottom). */
  y: number;
  /** Optional radius hint for hit-testing (default 24 px in the rendered minimap). */
  radiusPx?: number;
}

export interface SceneNode {
  id: string;
  /** Human-readable name displayed in the chrome ("Lobby", "Showroom", "Balcony"). */
  name: string;
  /** Default panorama URL when no variant is active. */
  defaultPanoramaUrl: string;
  /** Default camera yaw on first entry (degrees, 0..360). */
  defaultYawDeg: number;
  /** Default camera pitch on first entry (degrees, -90..90). */
  defaultPitchDeg: number;
  /** Initial FOV in degrees — defaults to 75 if absent. */
  defaultFovDeg?: number;
  hotspots: readonly SceneHotspot[];
  /** Optional alternative renderings of the same scene (F-17). */
  variants?: readonly SceneVariant[];
  /** Optional label for the implicit "no variant" state in the picker.
   *  Defaults to "Default"; a day/night tour sets this to "☀️ Day". */
  defaultVariantLabel?: string;
  /** Optional anchor on the tour's minimap (F-15). */
  minimapAnchor?: MinimapAnchor;
}

export interface MinimapEdge {
  /** Scene id (the lower of the two ids alphabetically, for canonical ordering). */
  fromSceneId: string;
  toSceneId: string;
}

export interface SceneGraph {
  /** Slug → scene node. Lookups are case-sensitive. */
  scenes: ReadonlyMap<string, SceneNode>;
  /** The scene the navigator opens on by default (must exist in `scenes`). */
  rootSceneId: string;
  /** Optional dimensions for the minimap viewport. Defaults to {width:200,height:200}. */
  minimapViewBox?: { widthPx: number; heightPx: number };
}

export interface SceneGraphValidationIssue {
  code:
    | 'root_missing'
    | 'hotspot_target_missing'
    | 'duplicate_scene_id'
    | 'duplicate_hotspot_id'
    | 'duplicate_variant_id'
    | 'minimap_anchor_out_of_range';
  sceneId?: string;
  hotspotId?: string;
  variantId?: string;
  message: string;
}

export const buildSceneGraph = (input: {
  scenes: readonly SceneNode[];
  rootSceneId: string;
  minimapViewBox?: { widthPx: number; heightPx: number };
}): SceneGraph => {
  const scenes = new Map<string, SceneNode>();
  for (const scene of input.scenes) {
    scenes.set(scene.id, scene);
  }
  return {
    scenes,
    rootSceneId: input.rootSceneId,
    minimapViewBox: input.minimapViewBox,
  };
};

export const validateSceneGraph = (graph: SceneGraph): readonly SceneGraphValidationIssue[] => {
  const issues: SceneGraphValidationIssue[] = [];

  if (!graph.scenes.has(graph.rootSceneId)) {
    issues.push({
      code: 'root_missing',
      message: `rootSceneId "${graph.rootSceneId}" is not in scenes`,
    });
  }

  // Duplicate scene ids cannot exist after `buildSceneGraph` (Map enforces uniqueness),
  // but we still check the raw `scenes.values()` ids in case the caller constructed
  // a SceneGraph by hand.
  const sceneIds = new Set<string>();
  for (const scene of graph.scenes.values()) {
    if (sceneIds.has(scene.id)) {
      issues.push({
        code: 'duplicate_scene_id',
        sceneId: scene.id,
        message: `duplicate scene id "${scene.id}"`,
      });
    }
    sceneIds.add(scene.id);

    const hotspotIds = new Set<string>();
    for (const hotspot of scene.hotspots) {
      if (hotspotIds.has(hotspot.id)) {
        issues.push({
          code: 'duplicate_hotspot_id',
          sceneId: scene.id,
          hotspotId: hotspot.id,
          message: `scene "${scene.id}" has duplicate hotspot id "${hotspot.id}"`,
        });
      }
      hotspotIds.add(hotspot.id);

      if (!graph.scenes.has(hotspot.toSceneId)) {
        issues.push({
          code: 'hotspot_target_missing',
          sceneId: scene.id,
          hotspotId: hotspot.id,
          message: `scene "${scene.id}" hotspot "${hotspot.id}" points at missing scene "${hotspot.toSceneId}"`,
        });
      }
    }

    if (scene.variants !== undefined) {
      const variantIds = new Set<string>();
      for (const variant of scene.variants) {
        if (variantIds.has(variant.id)) {
          issues.push({
            code: 'duplicate_variant_id',
            sceneId: scene.id,
            variantId: variant.id,
            message: `scene "${scene.id}" has duplicate variant id "${variant.id}"`,
          });
        }
        variantIds.add(variant.id);
      }
    }

    if (scene.minimapAnchor !== undefined) {
      const { x, y } = scene.minimapAnchor;
      if (x < 0 || x > 1 || y < 0 || y > 1) {
        issues.push({
          code: 'minimap_anchor_out_of_range',
          sceneId: scene.id,
          message: `scene "${scene.id}" minimapAnchor must be in [0..1], got x=${x} y=${y}`,
        });
      }
    }
  }

  return issues;
};

/** BFS shortest path from `fromId` to `toId`. Returns the chain inclusive of both ends, or null if unreachable. */
export const findShortestPath = (
  graph: SceneGraph,
  fromId: string,
  toId: string,
): readonly string[] | null => {
  if (fromId === toId) return [fromId];
  if (!graph.scenes.has(fromId) || !graph.scenes.has(toId)) return null;

  const visited = new Set<string>([fromId]);
  const parents = new Map<string, string>();
  const queue: string[] = [fromId];

  while (queue.length > 0) {
    const current = queue.shift()!;
    const node = graph.scenes.get(current);
    if (node === undefined) continue;
    for (const hotspot of node.hotspots) {
      if (visited.has(hotspot.toSceneId)) continue;
      visited.add(hotspot.toSceneId);
      parents.set(hotspot.toSceneId, current);
      if (hotspot.toSceneId === toId) {
        // Reconstruct path back to fromId
        const path: string[] = [toId];
        let cursor: string | undefined = toId;
        while (cursor !== undefined && cursor !== fromId) {
          cursor = parents.get(cursor);
          if (cursor !== undefined) path.unshift(cursor);
        }
        return path;
      }
      queue.push(hotspot.toSceneId);
    }
  }
  return null;
};

/** Canonical (de-duplicated, alphabetically ordered) edges suitable for minimap rendering. */
export const minimapEdges = (graph: SceneGraph): readonly MinimapEdge[] => {
  const seen = new Set<string>();
  const edges: MinimapEdge[] = [];
  for (const scene of graph.scenes.values()) {
    for (const hotspot of scene.hotspots) {
      const [a, b] =
        scene.id < hotspot.toSceneId
          ? [scene.id, hotspot.toSceneId]
          : [hotspot.toSceneId, scene.id];
      const key = `${a}→${b}`;
      if (seen.has(key)) continue;
      seen.add(key);
      edges.push({ fromSceneId: a, toSceneId: b });
    }
  }
  return edges;
};

/** Returns true if there is at least one variant defined for the scene. */
export const sceneHasVariants = (scene: SceneNode | undefined): boolean =>
  scene?.variants !== undefined && scene.variants.length > 0;

/** Resolves the panorama URL to load for a (scene, optional variant) tuple. */
export const resolvePanoramaUrl = (scene: SceneNode, variantId?: string): string => {
  if (variantId === undefined) return scene.defaultPanoramaUrl;
  const v = scene.variants?.find((x) => x.id === variantId);
  return v?.panoramaUrl ?? scene.defaultPanoramaUrl;
};
