import type { CameraState } from './camera-controls';

/**
 * Touch + keyboard gesture polish for the viewer (FR-TVS-RND-006 + 007).
 *
 * Adds beyond S13's basic drag/pinch/arrow-key model:
 *   - Long-press detection (alternate POI activation on touch)
 *   - Inertial pan momentum after fast drag release
 *   - Horizontal swipe → previous/next scene (for monotone tours)
 *   - Extended keyboard map: Home (reset), PageUp/PageDown (scene step),
 *     Backspace (back), `[`/`]` (variant step)
 *
 * All pure functions / pure state machines — the viewer app supplies pointer/keyboard events.
 */

// ----- Long press --------------------------------------------------------------

export interface LongPressConfig {
  /** Milliseconds the pointer must stay down before firing (default 500ms). */
  thresholdMs?: number;
  /** Maximum movement during the press in pixels (default 8). */
  movementToleranceCss?: number;
}

export interface LongPressEvaluation {
  fired: boolean;
  cancelledReason?: 'movement' | 'lifted' | 'too_short';
}

export const evaluateLongPress = (args: {
  downAtMs: number;
  upOrCancelAtMs: number;
  totalMovementCss: number;
  config?: LongPressConfig;
}): LongPressEvaluation => {
  const threshold = args.config?.thresholdMs ?? 500;
  const tolerance = args.config?.movementToleranceCss ?? 8;
  if (args.totalMovementCss > tolerance) {
    return { fired: false, cancelledReason: 'movement' };
  }
  const elapsed = args.upOrCancelAtMs - args.downAtMs;
  if (elapsed < threshold) {
    return { fired: false, cancelledReason: 'too_short' };
  }
  return { fired: true };
};

// ----- Momentum drag -----------------------------------------------------------

export const DEFAULT_MOMENTUM_DECAY = 0.92;
export const DEFAULT_MOMENTUM_MIN_VELOCITY = 0.05;

export interface MomentumState {
  velocityX: number;
  velocityY: number;
}

/**
 * Apply one frame of momentum to the camera and return both the next
 * camera + the decayed velocity. Caller stops calling once velocity falls
 * below `minVelocity`.
 */
export const applyMomentumFrame = (args: {
  camera: CameraState;
  velocity: MomentumState;
  viewportWidthPx: number;
  viewportHeightPx: number;
  decay?: number;
  minVelocity?: number;
}): { camera: CameraState; velocity: MomentumState; settled: boolean } => {
  const decay = args.decay ?? DEFAULT_MOMENTUM_DECAY;
  const minV = args.minVelocity ?? DEFAULT_MOMENTUM_MIN_VELOCITY;
  // Reuse the drag math via small deltas — yaw degrees per px (mirror of applyDragPan).
  const yawPerPxDeg = (args.camera.fov / args.viewportWidthPx) * 0.6;
  const pitchPerPxDeg = (args.camera.fov / args.viewportHeightPx) * 0.6;
  const nextYaw = args.camera.yaw - args.velocity.velocityX * yawPerPxDeg;
  let nextPitch = args.camera.pitch + args.velocity.velocityY * pitchPerPxDeg;
  if (nextPitch > 89) nextPitch = 89;
  if (nextPitch < -89) nextPitch = -89;
  const nextVel: MomentumState = {
    velocityX: args.velocity.velocityX * decay,
    velocityY: args.velocity.velocityY * decay,
  };
  const settled = Math.abs(nextVel.velocityX) < minV && Math.abs(nextVel.velocityY) < minV;
  return {
    camera: { ...args.camera, yaw: normaliseYaw(nextYaw), pitch: nextPitch },
    velocity: nextVel,
    settled,
  };
};

const normaliseYaw = (yaw: number): number => {
  let next = yaw % 360;
  if (next < 0) next += 360;
  return next;
};

// ----- Swipe-to-navigate -------------------------------------------------------

export type SwipeOutcome = 'previous_scene' | 'next_scene' | 'none';

export const interpretHorizontalSwipe = (args: {
  deltaPx: number;
  durationMs: number;
  /** Minimum horizontal travel in CSS pixels to count as a swipe (default 80). */
  minTravelPx?: number;
  /** Maximum duration in ms to count as a swipe (default 400). */
  maxDurationMs?: number;
}): SwipeOutcome => {
  const minTravel = args.minTravelPx ?? 80;
  const maxDuration = args.maxDurationMs ?? 400;
  if (args.durationMs > maxDuration) return 'none';
  if (args.deltaPx <= -minTravel) return 'next_scene';
  if (args.deltaPx >= minTravel) return 'previous_scene';
  return 'none';
};

// ----- Extended keyboard map ---------------------------------------------------

export type NavCommand =
  | { kind: 'reset_view' }
  | { kind: 'back' }
  | { kind: 'next_scene' }
  | { kind: 'previous_scene' }
  | { kind: 'next_variant' }
  | { kind: 'previous_variant' };

export const mapKeyToNavCommand = (args: { key: string }): NavCommand | null => {
  switch (args.key) {
    case 'Home':
      return { kind: 'reset_view' };
    case 'Backspace':
      return { kind: 'back' };
    case 'PageDown':
      return { kind: 'next_scene' };
    case 'PageUp':
      return { kind: 'previous_scene' };
    case ']':
      return { kind: 'next_variant' };
    case '[':
      return { kind: 'previous_variant' };
    default:
      return null;
  }
};

// ----- Tab-order for keyboard a11y --------------------------------------------

export interface FocusableItem {
  id: string;
  xPx: number;
  yPx: number;
  group: 'poi' | 'hotspot';
}

/** Stable tab order: hotspots first, then POIs; within each group, top-to-bottom then left-to-right. */
export const orderFocusables = (items: readonly FocusableItem[]): readonly string[] => {
  const sortable = items.slice();
  sortable.sort((a, b) => {
    if (a.group !== b.group) return a.group === 'hotspot' ? -1 : 1;
    if (a.yPx !== b.yPx) return a.yPx - b.yPx;
    return a.xPx - b.xPx;
  });
  return sortable.map((x) => x.id);
};
