/**
 * Visitor chip overlay tuned for the procedural-room renderer.
 *
 * The original `visitor-effects.ts` projects chip anchors through a
 * panorama camera (yaw / pitch / fov) — which does not match the
 * Three.js perspective camera the procedural-room renderer uses, so
 * its chips land off-screen.
 *
 * This module renders a fixed bottom-of-screen chip row (one chip per
 * tappable twin) that:
 *   - is always visible regardless of camera orientation
 *   - reads its state from the registry every render so the chip
 *     label tracks the live twin state (`Light on` ↔ `Light off`)
 *   - dispatches a `visitorToggle` on click and lets the caller pipe
 *     the result into the renderer's `updateTwinState`
 */

import {
  visitorTappableTwinIds,
  visitorToggle,
  type TenantInteractionCapabilities,
  type Twin,
  type TwinAuditEntry,
  type TwinRegistry,
  type TwinState,
} from '@nova/digital-twin';

export interface ProceduralChipOverlayArgs {
  readonly hostEl: HTMLElement;
  readonly registry: TwinRegistry;
  readonly sceneId: string;
  readonly capabilities: TenantInteractionCapabilities;
  readonly sessionId: string;
  readonly onInteraction: (audit: TwinAuditEntry) => void;
}

export interface ProceduralChipOverlayHandle {
  refresh(): void;
  dispose(): void;
}

export function mountProceduralChipOverlay(
  args: ProceduralChipOverlayArgs,
): ProceduralChipOverlayHandle {
  const root = document.createElement('div');
  root.className = 'nova-procedural-chips';
  root.setAttribute('aria-label', 'Interactive scene controls');
  root.style.cssText = `
    position: absolute;
    inset-inline: 0;
    bottom: 0;
    padding: 16px 20px env(safe-area-inset-bottom, 16px) 20px;
    background: linear-gradient(to top, rgba(15, 23, 42, 0.92), rgba(15, 23, 42, 0));
    z-index: 50;
    display: flex;
    flex-wrap: wrap;
    gap: 12px;
    justify-content: center;
    pointer-events: none;
  `;
  args.hostEl.appendChild(root);

  const buttons = new Map<string, HTMLButtonElement>();

  function render(): void {
    const tappable = new Set(
      visitorTappableTwinIds(args.registry, args.sceneId, args.capabilities),
    );
    const visible = new Set<string>();
    for (const twin of args.registry.twinsForScene(args.sceneId)) {
      if (!tappable.has(twin.id)) continue;
      visible.add(twin.id);
      let btn = buttons.get(twin.id);
      if (!btn) {
        btn = buildButton(twin);
        btn.addEventListener('click', () => handleToggle(twin.id));
        btn.addEventListener('keydown', (e) => {
          if (e.key === 'Enter' || e.key === ' ') {
            e.preventDefault();
            handleToggle(twin.id);
          }
        });
        root.appendChild(btn);
        buttons.set(twin.id, btn);
      }
      applyButtonState(btn, twin.label, twin.state);
    }
    for (const [id, btn] of buttons) {
      if (!visible.has(id)) {
        btn.remove();
        buttons.delete(id);
      }
    }
  }

  function handleToggle(twinId: string): void {
    const result = visitorToggle(args.registry, args.capabilities, {
      twinId,
      sessionId: args.sessionId,
    });
    if (!result.ok) return;
    args.onInteraction(result.audit);
    render();
  }

  render();

  return {
    refresh: render,
    dispose(): void {
      root.remove();
      buttons.clear();
    },
  };
}

function buildButton(twin: Twin): HTMLButtonElement {
  const btn = document.createElement('button');
  btn.type = 'button';
  btn.className = 'nova-procedural-chip';
  btn.dataset.twinId = twin.id;
  btn.setAttribute('role', 'button');
  btn.setAttribute('tabindex', '0');
  btn.setAttribute('aria-label', `Toggle ${twin.label}`);
  btn.style.cssText = `
    pointer-events: auto;
    min-width: 140px;
    min-height: 48px;
    padding: 10px 18px;
    border-radius: 24px;
    border: 1px solid rgba(255, 255, 255, 0.25);
    background: linear-gradient(135deg, rgba(8, 47, 73, 0.92), rgba(2, 132, 199, 0.92));
    color: #f8fafc;
    font: 600 14px/1.2 system-ui, -apple-system, Segoe UI, sans-serif;
    cursor: pointer;
    user-select: none;
    backdrop-filter: blur(8px);
    box-shadow: 0 10px 28px rgba(0, 0, 0, 0.45);
    transition:
      transform 160ms ease,
      box-shadow 160ms ease,
      background 220ms ease;
    display: inline-flex;
    align-items: center;
    gap: 8px;
  `;
  btn.addEventListener('mouseenter', () => {
    btn.style.transform = 'translateY(-2px)';
  });
  btn.addEventListener('mouseleave', () => {
    btn.style.transform = '';
  });
  return btn;
}

function applyButtonState(btn: HTMLButtonElement, label: string, state: TwinState): void {
  switch (state.kind) {
    case 'lamp': {
      const on = state.state.on;
      btn.textContent = on ? `◉ ${label}: on` : `○ ${label}: off`;
      btn.style.background = on
        ? 'radial-gradient(circle at 30% 30%, rgba(254, 215, 102, 0.95), rgba(245, 158, 11, 0.85))'
        : 'linear-gradient(135deg, rgba(30, 41, 59, 0.92), rgba(15, 23, 42, 0.92))';
      btn.style.color = on ? '#1e1b0a' : '#f8fafc';
      break;
    }
    case 'door': {
      const open = state.state.open;
      btn.textContent = open
        ? `◖ ${label}: open`
        : state.state.locked
          ? `🔒 ${label}: locked`
          : `▮ ${label}: closed`;
      btn.style.background = open
        ? 'linear-gradient(135deg, rgba(34, 197, 94, 0.92), rgba(16, 185, 129, 0.92))'
        : 'linear-gradient(135deg, rgba(71, 85, 105, 0.92), rgba(51, 65, 85, 0.92))';
      break;
    }
    case 'shade': {
      const open = state.state.position < 0.5;
      btn.textContent = open ? `▭ ${label}: open` : `▬ ${label}: closed`;
      btn.style.background = open
        ? 'linear-gradient(135deg, rgba(125, 211, 252, 0.92), rgba(56, 189, 248, 0.92))'
        : 'linear-gradient(135deg, rgba(71, 85, 105, 0.92), rgba(51, 65, 85, 0.92))';
      btn.style.color = open ? '#0c2540' : '#f8fafc';
      break;
    }
    case 'media-display': {
      const on = state.state.playing;
      btn.textContent = on ? `▶ ${label}: on` : `■ ${label}: off`;
      btn.style.background = on
        ? 'linear-gradient(135deg, rgba(239, 68, 68, 0.92), rgba(220, 38, 38, 0.92))'
        : 'linear-gradient(135deg, rgba(71, 85, 105, 0.92), rgba(51, 65, 85, 0.92))';
      break;
    }
    default:
      btn.textContent = `• ${label}`;
      break;
  }
}
