import { ALL_INTERACTIONS_ON, TwinRegistry, visitorToggle } from '@nova/digital-twin';
import {
  applyKeyboardCommand,
  compassLabel,
  DEFAULT_CAMERA,
  directionForLocale,
  mapKeyToCommand,
  mapKeyToNavCommand,
  markFirstPaintBoot,
  markFirstPaintCapability,
  markFirstPaintFirstTile,
  markFirstPaintInteractive,
  pickBestLocale,
  pickInitialLod,
  readQualitySignals,
  renderCapabilityMessage,
  reportFirstPaint,
  sceneHasVariants,
  SceneNavigator,
  ViewerStateMachine,
  type CameraState,
  type SceneNavigatorChange,
} from '@nova/viewer-core';

import { mountProceduralChipOverlay } from './digital-twin/procedural-chip-overlay';
import { mountSceneEffectsChips } from './digital-twin/scene-effects-chips';
import { mountTourEffects } from './digital-twin/tour-effects';
import { mountVisitorEffects } from './digital-twin/visitor-effects';
import { SceneStateController } from './fx/scene-state-controller';
import { mountHotspotOverlay, type HotspotOverlayHandle } from './nav/hotspot-overlay';
import { mountLightSwitchOverlay, type LightSwitchOverlayHandle } from './nav/light-switch-overlay';
import { mountMinimap, type MinimapHandle } from './nav/minimap';
import { mountVariantPicker, type VariantPickerHandle } from './nav/scene-variant-picker';
import { DEMO_POIS } from './poi/demo-pois';
import { mountPoiOverlay, type PoiOverlayHandle } from './poi/poi-overlay';
import { mountPanoramaRenderer, type PanoramaRendererHandle } from './renderer/panorama-renderer';
import { mountProceduralRoom } from './renderer/procedural-room-renderer';
import { DEMO_SCENE_GRAPH } from './scenes/demo-scene-graph';
import { LIVING_ROOM_SPEC } from './scenes/procedural-room-spec';
import { REAL_TOUR_GRAPH, REAL_TOUR_TWINS } from './scenes/real-tour-graph';
import { VILLA_INTERACTIVE, VILLA_POIS, VILLA_TOUR_GRAPH } from './scenes/villa-tour-graph';

/**
 * Viewer entry. Boot flow:
 *
 *   1. mark `paint:nova:boot`
 *   2. detect renderer backend → show capability-failed if none
 *   3. mark `paint:nova:capability`
 *   4. resolve language preference + apply [dir]
 *   5. dynamic-import Three.js wrapper + mount renderer onto #viewer-canvas
 *   6. wire SceneNavigator → renderer swap on every scene change
 *   7. mount POI + hotspot + minimap + variant-picker overlays
 *   8. bind input layer + reveal chrome → mark `paint:nova:interactive`
 *
 * S15 adds the SceneNavigator + multi-scene panorama swap; the renderer
 * exposes `setPanorama(url)` for in-place texture replacement so we don't
 * re-init Three.js on every teleport.
 */

markFirstPaintBoot();

const SUPPORTED_LANGUAGES = ['en-US', 'ar-KW', 'ar-SA', 'ar-EG', 'fr-FR'];
const DEFAULT_LANGUAGE = 'en-US';

const state = new ViewerStateMachine();

const elements = {
  canvas: document.getElementById('viewer-canvas') as HTMLDivElement,
  loading: document.getElementById('viewer-loading')!,
  loadingBar: document.getElementById('viewer-loading-bar-fill')!,
  loadingLabel: document.getElementById('viewer-loading-label')!,
  capabilityError: document.getElementById('viewer-capability-error')!,
  capabilityTitle: document.getElementById('capability-title')!,
  capabilityBody: document.getElementById('capability-body')!,
  capabilityRecommendations: document.getElementById(
    'capability-recommendations',
  ) as HTMLUListElement,
  compass: document.getElementById('viewer-compass')!,
  compassNeedle: document.getElementById('viewer-compass-needle')!,
  compassLabel: document.getElementById('viewer-compass-label')!,
  pitchIndicator: document.getElementById('viewer-pitch-indicator')!,
  sceneTitle: document.getElementById('viewer-scene-title')!,
  history: document.getElementById('viewer-history')!,
  backBtn: document.getElementById('viewer-back-btn') as HTMLButtonElement,
  forwardBtn: document.getElementById('viewer-forward-btn') as HTMLButtonElement,
  controls: document.getElementById('viewer-controls-hint')!,
  fullscreenBtn: document.getElementById('viewer-fullscreen-btn') as HTMLButtonElement,
  resetBtn: document.getElementById('viewer-reset-view-btn') as HTMLButtonElement,
  helpBtn: document.getElementById('viewer-help-btn') as HTMLButtonElement,
  help: document.getElementById('viewer-help')!,
  helpClose: document.getElementById('viewer-help-close') as HTMLButtonElement,
  root: document.documentElement,
};

const applyLocale = (): void => {
  const supported = pickBestLocale(
    navigator.languages ?? [],
    SUPPORTED_LANGUAGES,
    DEFAULT_LANGUAGE,
  );
  elements.root.lang = supported;
  elements.root.dir = directionForLocale(supported);
};

const showCapabilityError = (reason: string): void => {
  const msg = renderCapabilityMessage('none');
  elements.capabilityTitle.textContent = msg.title;
  elements.capabilityBody.textContent = `${msg.body} (${reason})`;
  elements.capabilityRecommendations.innerHTML = '';
  for (const rec of msg.recommendations) {
    const li = document.createElement('li');
    li.textContent = rec;
    elements.capabilityRecommendations.appendChild(li);
  }
  elements.loading.hidden = true;
  elements.capabilityError.hidden = false;
};

let renderer: PanoramaRendererHandle | null = null;
let poiOverlay: PoiOverlayHandle | null = null;
let hotspotOverlay: HotspotOverlayHandle | null = null;
let minimap: MinimapHandle | null = null;
let variantPicker: VariantPickerHandle | null = null;
let lightSwitchOverlay: LightSwitchOverlayHandle | null = null;
let cameraState: CameraState = { ...DEFAULT_CAMERA };
// Switch scene graph based on the ?scene= query param at boot time.
//   villa     → CGI villa tour (6 Blender-rendered day/night panoramas)
//   real-tour → CC0 Poly Haven panoramas (REAL_TOUR_GRAPH)
//   (default) → the original demo graph.
const __sceneMode =
  typeof window !== 'undefined' ? new URLSearchParams(window.location.search).get('scene') : null;
const ACTIVE_GRAPH =
  __sceneMode === 'villa'
    ? VILLA_TOUR_GRAPH
    : __sceneMode === 'real-tour'
      ? REAL_TOUR_GRAPH
      : DEMO_SCENE_GRAPH;
const navigator_ = new SceneNavigator({ graph: ACTIVE_GRAPH });

const refreshCompass = (next: CameraState): void => {
  cameraState = next;
  const bearing = compassLabel(next.yaw, 0);
  elements.compassLabel.textContent = bearing;
  elements.compassNeedle.style.transform = `rotate(${(-next.yaw).toFixed(1)}deg)`;
  elements.pitchIndicator.textContent = `${Math.round(next.pitch)}°`;
  renderer?.setCamera(next);
  poiOverlay?.update(next);
  hotspotOverlay?.update(next);
  lightSwitchOverlay?.update(next);
  minimap?.setCamera(next);
};

/**
 * Load a scene's panorama. For the villa's interactive NIGHT scenes this
 * loads the dark base + the per-room light LAYERS and mounts the clickable
 * light switches (real rendered lights you can toggle); for everything else
 * it just swaps the single panorama texture + clears any layers/switches.
 */
const applyScenePanorama = async (
  sceneId: string,
  variantId: string | undefined,
  fallbackUrl: string,
): Promise<void> => {
  if (renderer === null) return;
  const interactive =
    __sceneMode === 'villa' && variantId === 'night' ? VILLA_INTERACTIVE[sceneId] : undefined;
  lightSwitchOverlay?.dispose();
  lightSwitchOverlay = null;
  if (interactive) {
    await renderer.setPanorama({ url: interactive.baseUrl });
    await renderer.setLayers(interactive.layers);
    lightSwitchOverlay = mountLightSwitchOverlay({
      hostEl: elements.canvas,
      switches: interactive.switches.map((s) => ({ ...s, on: true })),
      initialCamera: cameraState,
      onToggle: (id, on) => renderer?.setLayerVisible(id, on),
    });
  } else {
    await renderer.setLayers([]);
    await renderer.setPanorama({ url: fallbackUrl });
  }
};

const refreshHistoryButtons = (): void => {
  elements.backBtn.disabled = !navigator_.canGoBack();
  elements.forwardBtn.disabled = !navigator_.canGoForward();
};

/**
 * Rebuild the POI + hotspot overlays for the (now-current) scene.
 *
 * The variant picker is mounted lazily by `ensureVariantPicker()` once on
 * boot, then updated in place via `setScene` / `setCurrentVariant` so chip
 * clicks aren't subject to dispose+remount races.
 */
const rebuildSceneOverlays = (): void => {
  const scene = navigator_.getCurrentScene();
  poiOverlay?.dispose();
  hotspotOverlay?.dispose();

  // POI overlay — product/media hotspots. The villa tour serves per-scene
  // product POIs (price/specs/video); the demo graph paints DEMO_POIS on the
  // lobby. Both render via the same overlay + 16 card renderers.
  const scenePois =
    __sceneMode === 'villa' ? (VILLA_POIS[scene.id] ?? []) : scene.id === 'lobby' ? DEMO_POIS : [];
  poiOverlay =
    scenePois.length > 0
      ? mountPoiOverlay({
          hostEl: elements.canvas,
          pois: scenePois,
          initialCamera: cameraState,
          locale: elements.root.lang,
          isRtl: elements.root.dir === 'rtl',
          onCta: (kind, payload) => {
            // eslint-disable-next-line no-console
            console.info('[viewer] POI CTA', kind, payload);
          },
        })
      : null;

  hotspotOverlay = mountHotspotOverlay({
    hostEl: elements.canvas,
    scene,
    initialCamera: cameraState,
    onTeleport: (hotspot) => {
      navigator_.teleport({
        toSceneId: hotspot.toSceneId,
        arriveYawDeg: hotspot.arriveYawDeg,
        arrivePitchDeg: hotspot.arrivePitchDeg,
        transition: hotspot.transition,
      });
    },
  });

  if (variantPicker === null) {
    variantPicker = mountVariantPicker({
      hostEl: elements.canvas,
      scene,
      currentVariantId: navigator_.currentVariantId,
      onSelect: (variantId) => navigator_.setVariant(variantId),
    });
  } else {
    variantPicker.setScene(scene, navigator_.currentVariantId);
  }
};

// Walk-through transition: a forward "dolly" — narrow the FOV (push into the
// scene) on the outgoing panorama, swap, arrive zoomed-in, then ease the FOV
// back out. Combined with the cross-fade it reads as stepping forward into the
// next spot (the 3DVista "3D transition" feel) instead of a hard cut.
let transitionSeq = 0;
const easeInOut = (t: number): number => (t < 0.5 ? 2 * t * t : 1 - Math.pow(-2 * t + 2, 2) / 2);
const animateFov = (from: number, to: number, durMs: number, seq: number, done?: () => void): void => {
  const start = performance.now();
  const step = (): void => {
    if (seq !== transitionSeq) return; // superseded by a newer transition
    const t = Math.min(1, (performance.now() - start) / durMs);
    refreshCompass({ ...cameraState, fov: from + (to - from) * easeInOut(t) });
    if (t < 1) requestAnimationFrame(step);
    else done?.();
  };
  requestAnimationFrame(step);
};

const onSceneChange = (change: SceneNavigatorChange): void => {
  // Update the chrome eagerly — these reflect the navigator state and are
  // independent of when the new panorama texture finishes streaming.
  const scene = navigator_.getCurrentScene();
  elements.sceneTitle.textContent = scene.name;
  elements.sceneTitle.hidden = false;
  elements.history.hidden = false;
  refreshHistoryButtons();
  minimap?.setCurrentScene(scene.id);

  if (renderer === null) return; // initial mount handled by main()

  // Variant flips stay on the current scene — only the panorama texture
  // changes. Skip the camera reset + overlay rebuild so the user keeps
  // their viewing angle when toggling day/night/etc.
  const isVariantFlip = change.cause === 'variant' && change.fromSceneId === change.toSceneId;
  if (isVariantFlip) {
    variantPicker?.setCurrentVariant(change.variantId);
    elements.canvas.classList.add('is-transitioning');
    void applyScenePanorama(change.toSceneId, change.variantId, change.panoramaUrl).finally(() =>
      elements.canvas.classList.remove('is-transitioning'),
    );
    return;
  }

  const targetFov = scene.defaultFovDeg ?? DEFAULT_CAMERA.fov;
  const nearFov = Math.max(38, targetFov - 30); // "pushed-in" FOV during the step
  const seq = ++transitionSeq;
  rebuildSceneOverlays();
  elements.canvas.classList.add('is-transitioning');

  // Phase 1 — dolly IN on the outgoing view (step toward the next spot).
  animateFov(cameraState.fov, nearFov, 300, seq, () => {
    if (seq !== transitionSeq) return;
    // Arrive at the destination orientation, still zoomed in.
    cameraState = { yaw: change.arriveYawDeg, pitch: change.arrivePitchDeg, fov: nearFov };
    refreshCompass(cameraState);
    // Phase 2 — swap the panorama, then ease the FOV back out (settle).
    void applyScenePanorama(scene.id, change.variantId, change.panoramaUrl)
      .then(() => {
        elements.canvas.classList.remove('is-transitioning');
        animateFov(nearFov, targetFov, 460, seq);
      })
      .catch((err: unknown) => {
        elements.canvas.classList.remove('is-transitioning');
        const message = err instanceof Error ? err.message : String(err);
        state.dispatch({ kind: 'fatal_error', code: 'SCENE_SWAP_FAILED', message });
      });
  });
};

const cycleScene = (direction: 1 | -1): void => {
  const sceneIds = [...ACTIVE_GRAPH.scenes.keys()];
  const current = navigator_.currentSceneId;
  const idx = sceneIds.indexOf(current);
  const nextIdx = (idx + direction + sceneIds.length) % sceneIds.length;
  const nextId = sceneIds[nextIdx];
  if (nextId !== undefined && nextId !== current) navigator_.jumpTo(nextId);
};

const cycleVariant = (direction: 1 | -1): void => {
  const scene = navigator_.getCurrentScene();
  if (!sceneHasVariants(scene)) return;
  const ids: (string | undefined)[] = [undefined, ...(scene.variants ?? []).map((v) => v.id)];
  const current = navigator_.currentVariantId;
  const idx = ids.indexOf(current);
  const nextIdx = (idx + direction + ids.length) % ids.length;
  navigator_.setVariant(ids[nextIdx]);
};

const bindControls = (): void => {
  elements.resetBtn.addEventListener('click', () => {
    const scene = navigator_.getCurrentScene();
    refreshCompass({
      yaw: scene.defaultYawDeg,
      pitch: scene.defaultPitchDeg,
      fov: scene.defaultFovDeg ?? DEFAULT_CAMERA.fov,
    });
  });

  elements.fullscreenBtn.addEventListener('click', () => {
    if (document.fullscreenElement !== null) {
      void document.exitFullscreen();
    } else {
      void document.documentElement.requestFullscreen();
    }
  });

  elements.helpBtn.addEventListener('click', () => {
    elements.help.hidden = false;
    elements.helpClose.focus();
  });

  elements.helpClose.addEventListener('click', () => {
    elements.help.hidden = true;
    elements.helpBtn.focus();
  });

  elements.backBtn.addEventListener('click', () => navigator_.back());
  elements.forwardBtn.addEventListener('click', () => navigator_.forward());

  document.addEventListener('keydown', (event) => {
    if (!elements.help.hidden && event.key === 'Escape') {
      event.preventDefault();
      elements.help.hidden = true;
      elements.helpBtn.focus();
      return;
    }

    // S15 extended nav commands (Home, PageUp/Down, Backspace, [/]).
    const navCmd = mapKeyToNavCommand({ key: event.key });
    if (navCmd !== null) {
      event.preventDefault();
      switch (navCmd.kind) {
        case 'reset_view': {
          const scene = navigator_.getCurrentScene();
          refreshCompass({
            yaw: scene.defaultYawDeg,
            pitch: scene.defaultPitchDeg,
            fov: scene.defaultFovDeg ?? DEFAULT_CAMERA.fov,
          });
          return;
        }
        case 'back':
          if (navigator_.canGoBack()) navigator_.back();
          return;
        case 'next_scene':
          cycleScene(1);
          return;
        case 'previous_scene':
          cycleScene(-1);
          return;
        case 'next_variant':
          cycleVariant(1);
          return;
        case 'previous_variant':
          cycleVariant(-1);
          return;
      }
    }

    const command = mapKeyToCommand({ key: event.key });
    if (command === null) return;
    event.preventDefault();
    refreshCompass(applyKeyboardCommand(cameraState, command));
  });
};

const subscribeChrome = (): void => {
  state.subscribe((s) => {
    if (s.kind === 'LOADING_PANORAMA') {
      elements.loading.hidden = false;
      elements.loadingBar.style.width = `${Math.round(s.progress01 * 100)}%`;
      elements.loadingLabel.textContent = `Loading panorama… ${Math.round(s.progress01 * 100)}%`;
      return;
    }
    if (s.kind === 'READY') {
      elements.loading.hidden = true;
      elements.compass.hidden = false;
      elements.controls.hidden = false;
      return;
    }
    if (s.kind === 'CAPABILITY_FAILED') {
      showCapabilityError(s.reason);
      return;
    }
    if (s.kind === 'ERROR') {
      showCapabilityError(`${s.code}: ${s.message}`);
      return;
    }
  });
};

// ── procedural-room boot path ─────────────────────────────────────────
// When the URL carries `?scene=procedural-room`, mount the Three.js
// primitive scene from `LIVING_ROOM_SPEC` (S43) instead of a panorama.
// Visitor toggles flip the actual mesh state in real time (S45).

const bootProceduralRoom = (): void => {
  applyLocale();
  subscribeChrome();

  const signals = readQualitySignals();
  if (signals.backend === 'none') {
    state.dispatch({
      kind: 'capability_failed',
      reason: 'WebGPU and WebGL2 both unavailable',
    });
    markFirstPaintCapability();
    return;
  }
  state.dispatch({ kind: 'capability_resolved', backend: signals.backend });
  markFirstPaintCapability();

  // Register the spec's twins into a live registry.
  const registry = new TwinRegistry();
  for (const twin of LIVING_ROOM_SPEC.twins) registry.register(twin);

  // Mount the renderer.
  const renderer = mountProceduralRoom({
    mountEl: elements.canvas,
    spec: LIVING_ROOM_SPEC,
    initialCamera: { ...DEFAULT_CAMERA, fov: 70 },
  });

  // Scene-state controller (day/night + weather) → renderer env hooks.
  const sceneState = new SceneStateController({
    capabilities: ALL_INTERACTIONS_ON,
    hooks: {
      applyEnvironment: (args) => renderer.applyEnvironment(args.intensity, [0, 1, 0]),
      applySunDirection: (dir) => renderer.applyEnvironment(0.8, dir),
    },
  });
  // Drive the day/night cycle each frame.
  let lastMs = performance.now();
  const tick = (): void => {
    const now = performance.now();
    sceneState.tick(now - lastMs);
    lastMs = now;
    requestAnimationFrame(tick);
  };
  requestAnimationFrame(tick);

  // Visitor chip overlay — bottom-of-screen row, one chip per
  // tappable twin. (The world-anchor projection version in
  // visitor-effects.ts uses panorama-camera math that doesn't match
  // the Three.js perspective camera here.)
  const sessionId = `viewer_${Date.now()}`;
  void mountVisitorEffects; // retained for the panorama path
  const chips = mountProceduralChipOverlay({
    hostEl: elements.canvas,
    registry,
    sceneId: LIVING_ROOM_SPEC.sceneId,
    capabilities: ALL_INTERACTIONS_ON,
    sessionId,
    onInteraction: (audit) => {
      // After a visitor toggle, push the new state into the renderer.
      const twin = registry.get(audit.twinId);
      if (twin) renderer.updateTwinState(audit.twinId, twin.state);
    },
  });
  void chips;

  // Apply the spec's interactive defaults via visitorToggle so the
  // demo starts with everything in a known state. Skipped here so the
  // shopper sees the unlit room first.
  void visitorToggle;

  // The state machine guards `load_completed` behind a preceding
  // `load_started`. Procedural mode has no "loading" phase (no
  // panorama texture to fetch), so we dispatch both back-to-back to
  // transition: CAPABILITY_OK → LOADING_PANORAMA → READY. The READY
  // state is what `subscribeChrome` listens for to hide the loading
  // overlay + reveal the compass/controls chrome.
  state.dispatch({ kind: 'load_started', sceneId: LIVING_ROOM_SPEC.sceneId });
  state.dispatch({ kind: 'load_completed', sceneId: LIVING_ROOM_SPEC.sceneId });
  // Belt-and-braces: explicitly hide the loading overlay in case the
  // state-machine transition order ever diverges in future versions.
  elements.loading.hidden = true;
  elements.canvas.style.background = '#101820';

  markFirstPaintFirstTile();
  markFirstPaintInteractive();
  const report = reportFirstPaint();
  if (report !== null) {
    // eslint-disable-next-line no-console
    console.info('[viewer:procedural] first-paint', report);
  }

  // Dispose handler so the procedural renderer is torn down on hot-reload.
  (window as unknown as { __viewerDispose?: () => void }).__viewerDispose = (): void => {
    renderer.dispose();
  };
};

// ── real-tour boot path ──────────────────────────────────────────────
// ?scene=real-tour mounts the panorama renderer over the existing
// SceneNavigator with the REAL_TOUR_GRAPH (4 CC0 Poly Haven photos)
// + overlays the procedural chip overlay so the visitor can toggle
// twins per scene. Photo-real backdrop, system-driven interactivity.

const main = async (): Promise<void> => {
  // Mode switch:
  //   ?scene=procedural-room → Three.js primitive scene.
  //   ?scene=real-tour       → CC0 Poly Haven panorama tour + chips.
  //   (default)              → original panorama demo.
  const query = new URLSearchParams(window.location.search);
  if (query.get('scene') === 'procedural-room') {
    bootProceduralRoom();
    return;
  }
  const realTourMode = query.get('scene') === 'real-tour';
  // NOTE: the villa tour (?scene=villa) deliberately does NOT use the
  // overlay effect chips — its interactions are REAL rendered lighting states
  // (Day / Golden hour / Night) driven by the variant picker, not CSS tints.

  applyLocale();
  subscribeChrome();

  const signals = readQualitySignals();
  const backend = signals.backend;
  if (backend === 'none') {
    state.dispatch({
      kind: 'capability_failed',
      reason: 'WebGPU and WebGL2 both unavailable',
    });
    markFirstPaintCapability();
    return;
  }
  state.dispatch({ kind: 'capability_resolved', backend });
  markFirstPaintCapability();

  const initialLod = pickInitialLod(signals);
  const rootScene = navigator_.getCurrentScene();
  cameraState = {
    yaw: rootScene.defaultYawDeg,
    pitch: rootScene.defaultPitchDeg,
    fov: rootScene.defaultFovDeg ?? DEFAULT_CAMERA.fov,
  };
  state.dispatch({ kind: 'load_started', sceneId: rootScene.id });

  try {
    renderer = await mountPanoramaRenderer({
      mountEl: elements.canvas,
      backend,
      initialCamera: cameraState,
      onCameraChange: (next) => refreshCompass(next),
      onLoadProgress: (progress01) => {
        state.dispatch({ kind: 'load_progress', sceneId: rootScene.id, progress01 });
      },
      onFirstTile: () => {
        markFirstPaintFirstTile();
      },
      panoramaUrl: rootScene.defaultPanoramaUrl,
      initialLod,
    });
    state.dispatch({ kind: 'load_completed', sceneId: rootScene.id });

    // Mount the minimap once — it tracks the navigator over the lifetime of the tour.
    minimap = mountMinimap({
      hostEl: elements.canvas,
      graph: ACTIVE_GRAPH,
      currentSceneId: rootScene.id,
      cameraFovDeg: cameraState.fov,
      cameraYawDeg: cameraState.yaw,
      onJumpTo: (sceneId) => navigator_.jumpTo(sceneId),
    });

    // Subscribe to scene changes BEFORE mounting so the initial scene takes
    // the same code path as a teleport (consistent chrome updates).
    navigator_.subscribe(onSceneChange);
    rebuildSceneOverlays();
    navigator_.mount();

    bindControls();
    markFirstPaintInteractive();

    // Real-photo tour (?scene=real-tour): overlay interactive chips per scene
    // + rebuild on scene change so the chip set matches the active room. The
    // tour-effects layer renders the visual + audio feedback (lamp glow, TV
    // screen, curtain dim, day/night tint, rain, doorbell) since the CC0
    // panorama meshes can't be lit/animated directly. (The villa tour skips
    // this — it uses real rendered lighting states via the variant picker.)
    if (realTourMode) {
      const realRegistry = new TwinRegistry();
      for (const twin of REAL_TOUR_TWINS) realRegistry.register(twin);
      const sessionId = `tour_${Date.now()}`;

      const effects = mountTourEffects({
        hostEl: elements.canvas,
        registry: realRegistry,
        initialSceneId: navigator_.currentSceneId,
      });

      mountSceneEffectsChips({
        hostEl: elements.canvas,
        effects,
        capabilities: ALL_INTERACTIONS_ON,
      });

      const mountChips = (sceneId: string) =>
        mountProceduralChipOverlay({
          hostEl: elements.canvas,
          registry: realRegistry,
          sceneId,
          capabilities: ALL_INTERACTIONS_ON,
          sessionId,
          onInteraction: (audit) => {
            effects.refreshFromRegistry();
            // eslint-disable-next-line no-console
            console.info('[real-tour] toggled', audit.twinId, audit.after);
          },
        });

      let chipOverlay = mountChips(navigator_.currentSceneId);
      navigator_.subscribe((change) => {
        chipOverlay.dispose();
        chipOverlay = mountChips(change.toSceneId);
        effects.setSceneId(change.toSceneId);
      });
    }

    const report = reportFirstPaint();
    if (report !== null) {
      // eslint-disable-next-line no-console
      console.info('[viewer] first-paint', report);
    }
  } catch (err) {
    const message = err instanceof Error ? err.message : String(err);
    state.dispatch({ kind: 'fatal_error', code: 'RENDERER_INIT_FAILED', message });
  }
};

void main();
