import { sceneHasVariants, type SceneNode } from '@nova/viewer-core';

/**
 * Scene variant picker (F-17) — bottom-left chip cluster showing all variants
 * of the current scene. Hidden when the scene has no variants.
 *
 * State is kept on the buttons themselves (aria-pressed) so dispose+remount
 * cycles are not needed for variant flips — `setCurrentVariant(id)` updates
 * the active chip in place. `setScene` rebuilds the chip list when the
 * underlying scene changes.
 */

export interface VariantPickerArgs {
  hostEl: HTMLElement;
  scene: SceneNode;
  currentVariantId: string | undefined;
  onSelect: (variantId: string | undefined) => void;
}

export interface VariantPickerHandle {
  setScene(scene: SceneNode, currentVariantId: string | undefined): void;
  setCurrentVariant(variantId: string | undefined): void;
  dispose(): void;
}

interface ChipMeta {
  variantId: string | undefined; // undefined = "Default"
  button: HTMLButtonElement;
}

export const mountVariantPicker = (args: VariantPickerArgs): VariantPickerHandle => {
  const root = document.createElement('div');
  root.className = 'viewer-variant-picker';
  root.setAttribute('data-testid', 'viewer-variant-picker');
  root.setAttribute('role', 'group');
  root.setAttribute('aria-label', 'Scene variants');
  args.hostEl.appendChild(root);

  let chips: ChipMeta[] = [];
  let currentScene: SceneNode = args.scene;
  let currentVariantId: string | undefined = args.currentVariantId;

  const setActive = (variantId: string | undefined): void => {
    currentVariantId = variantId;
    for (const chip of chips) {
      const isActive = chip.variantId === variantId;
      chip.button.classList.toggle('is-active', isActive);
      chip.button.setAttribute('aria-pressed', isActive ? 'true' : 'false');
    }
  };

  const rebuild = (): void => {
    root.replaceChildren();
    chips = [];
    if (!sceneHasVariants(currentScene)) {
      root.hidden = true;
      return;
    }
    root.hidden = false;

    const heading = document.createElement('span');
    heading.className = 'viewer-variant-heading';
    heading.textContent = 'Variant:';
    root.appendChild(heading);

    const make = (label: string, variantId: string | undefined): HTMLButtonElement => {
      const btn = document.createElement('button');
      btn.type = 'button';
      btn.className = 'viewer-variant-chip';
      btn.textContent = label;
      btn.addEventListener('click', () => {
        setActive(variantId); // update UI eagerly so the user sees it
        args.onSelect(variantId);
      });
      root.appendChild(btn);
      chips.push({ variantId, button: btn });
      return btn;
    };

    make(currentScene.defaultVariantLabel ?? 'Default', undefined);
    for (const v of currentScene.variants ?? []) make(v.label, v.id);

    setActive(currentVariantId);
  };

  rebuild();

  return {
    setScene(scene, variantId): void {
      currentScene = scene;
      currentVariantId = variantId;
      rebuild();
    },
    setCurrentVariant(variantId): void {
      setActive(variantId);
    },
    dispose(): void {
      if (root.parentElement === args.hostEl) args.hostEl.removeChild(root);
    },
  };
};
