/**
 * Renderer-capability detection (FR-TVS-RND-001 + FR-TVS-RND-005).
 *
 * The viewer auto-detects the rendering backend in priority order:
 *   1. WebGPU (modern Chrome / Edge / Safari 17+) — preferred for the
 *      8K HDR + Gaussian Splat workloads.
 *   2. WebGL2 (universal fallback).
 *   3. None — show a friendly upgrade-your-browser screen.
 *
 * This module is intentionally side-effect-free + framework-agnostic so it
 * can be unit-tested in Node (jsdom isn't required — we only inspect
 * `globalThis.navigator` / `globalThis.WebGL2RenderingContext`).
 *
 * Adaptive-quality (FR-TVS-RND-005) reads `navigator.connection.effectiveType`
 * (Network Information API) + `navigator.deviceMemory` + `navigator.hardwareConcurrency`
 * to pick a resolution tier. Each LOD level corresponds to a key in the
 * panorama's `lodTiles` manifest from `@nova/media`.
 */

export type RendererBackend = 'webgpu' | 'webgl2' | 'none';

export interface CapabilityProbeWindow {
  readonly navigator?: {
    readonly gpu?: unknown;
    readonly deviceMemory?: number;
    readonly hardwareConcurrency?: number;
    readonly connection?: {
      /** Effective network type. Common values: 'slow-2g' | '2g' | '3g' | '4g' (Network Information API). */
      readonly effectiveType?: string;
      readonly downlink?: number;
    };
    readonly languages?: readonly string[];
    readonly language?: string;
  };
  readonly WebGL2RenderingContext?: unknown;
}

export const detectRendererBackend = (
  probe: CapabilityProbeWindow = globalThis,
): RendererBackend => {
  if (probe.navigator?.gpu !== undefined && probe.navigator.gpu !== null) {
    return 'webgpu';
  }
  if (probe.WebGL2RenderingContext !== undefined && probe.WebGL2RenderingContext !== null) {
    return 'webgl2';
  }
  return 'none';
};

export type LodTier = '8k' | '4k' | '2k' | '1k';

export interface QualitySignals {
  effectiveType?: string;
  downlinkMbps?: number;
  deviceMemoryGiB?: number;
  hardwareConcurrency?: number;
  backend: RendererBackend;
}

export const readQualitySignals = (probe: CapabilityProbeWindow = globalThis): QualitySignals => {
  const nav = probe.navigator;
  const signals: QualitySignals = { backend: detectRendererBackend(probe) };
  const eff = nav?.connection?.effectiveType;
  if (typeof eff === 'string') signals.effectiveType = eff;
  if (typeof nav?.connection?.downlink === 'number') signals.downlinkMbps = nav.connection.downlink;
  if (typeof nav?.deviceMemory === 'number') signals.deviceMemoryGiB = nav.deviceMemory;
  if (typeof nav?.hardwareConcurrency === 'number') {
    signals.hardwareConcurrency = nav.hardwareConcurrency;
  }
  return signals;
};

/**
 * Pick a starting LOD level given the detected signals.
 *
 * Tiers are conservative on purpose; the runtime upgrade-on-spare-bandwidth
 * loop (S35 LOD streaming) is the one that actually walks up to 8K. The
 * INITIAL pick must protect the FR-TVS-RND-002 ≤2.5s first-paint budget
 * on a 10 Mbps link.
 */
export const pickInitialLod = (signals: QualitySignals): LodTier => {
  if (signals.backend === 'none') return '1k';
  if (signals.effectiveType === 'slow-2g' || signals.effectiveType === '2g') return '1k';
  if (signals.effectiveType === '3g') return '2k';
  if (signals.downlinkMbps !== undefined && signals.downlinkMbps < 5) return '2k';
  if (signals.backend === 'webgl2' && (signals.deviceMemoryGiB ?? 8) < 4) return '2k';
  if (signals.backend === 'webgpu' && (signals.deviceMemoryGiB ?? 8) >= 8) return '4k';
  return '4k';
};

/** Friendly capability message — surfaced when `backend === 'none'`. */
export interface CapabilityMessage {
  title: string;
  body: string;
  /** Suggested browsers / actions, copy is localisable by the host app. */
  recommendations: string[];
}

export const renderCapabilityMessage = (backend: RendererBackend): CapabilityMessage => {
  if (backend === 'none') {
    return {
      title: 'This browser cannot render the tour',
      body:
        'Your browser does not support WebGPU or WebGL2. Please update to a recent ' +
        'version of Chrome, Edge, Safari, or Firefox to view this tour.',
      recommendations: [
        'Update Chrome to version 113 or later',
        'Update Safari to version 17 or later',
        'Update Firefox to version 121 or later',
      ],
    };
  }
  return {
    title: 'Ready to render',
    body: `Renderer: ${backend.toUpperCase()}`,
    recommendations: [],
  };
};
