/**
 * Procedural-room Three.js renderer.
 *
 * Sibling of `panorama-renderer.ts`. When the tour scene is procedural
 * (a Three.js primitive composition — no .glb, no 360 panorama), this
 * file mounts the WebGLRenderer, walks the spec from
 * `apps/viewer/src/scenes/procedural-room-spec.ts`, builds the matching
 * Three.js objects, and returns a handle with:
 *
 *   - `setCamera(camera)`  — same shape as panorama-renderer for
 *     compatibility with the existing input layer.
 *   - `updateTwinState(twinId, state)` — visitor toggles call this;
 *     the renderer diffs the spec mutation against its mapped Three.js
 *     objects + applies the change in place (no full scene rebuild).
 *   - `applyEnvironment(intensity, sunDir)` — wired to the
 *     SceneStateController so day/night lerps the ambient + the
 *     directional sun in real time.
 *   - `dispose()` — disposes every geometry + material + render
 *     target.
 *
 * Three.js objects are tracked by spec id so the update path is O(1).
 */

import {
  AmbientLight,
  BoxGeometry,
  Color,
  CylinderGeometry,
  DirectionalLight,
  Mesh,
  MeshStandardMaterial,
  PCFSoftShadowMap,
  PerspectiveCamera,
  PlaneGeometry,
  PointLight,
  Scene,
  SphereGeometry,
  WebGLRenderer,
  type WebGLRendererParameters,
} from 'three';

import {
  findPrimitive,
  type PrimitiveSpec,
  type ProceduralRoomSpec,
} from '../scenes/procedural-room-spec';
import { applyTwinStateToSpec } from '../scenes/procedural-room-state';

import type { TwinState } from '@nova/digital-twin';
import type { CameraState } from '@nova/viewer-core';

export interface ProceduralRoomRendererArgs {
  readonly mountEl: HTMLElement;
  readonly spec: ProceduralRoomSpec;
  readonly initialCamera: CameraState;
  readonly onCameraChange?: (next: CameraState) => void;
}

export interface ProceduralRoomRendererHandle {
  setCamera(next: CameraState): void;
  /** Apply a twin state change — the matching primitive's transform/
   *  material updates in-place. */
  updateTwinState(twinId: string, state: TwinState): void;
  /** Wire from the SceneStateController for day/night response. */
  applyEnvironment(intensity: number, sunDir: readonly [number, number, number]): void;
  /** Spec snapshot — useful for the visitor overlay to project chip
   *  anchors against the live primitive positions. */
  currentSpec(): ProceduralRoomSpec;
  dispose(): void;
}

export const mountProceduralRoom = (
  args: ProceduralRoomRendererArgs,
): ProceduralRoomRendererHandle => {
  const rendererParams: WebGLRendererParameters = {
    antialias: true,
    alpha: false,
    powerPreference: 'high-performance',
  };
  const renderer = new WebGLRenderer(rendererParams);
  renderer.setPixelRatio(Math.min(window.devicePixelRatio, 2));
  // mountEl may have 0×0 dimensions briefly during first paint (Vite
  // dev server inserts elements before layout settles); fall back to
  // the visual viewport so we always start with a usable canvas size.
  const initialW = args.mountEl.clientWidth || window.innerWidth;
  const initialH = args.mountEl.clientHeight || window.innerHeight;
  renderer.setSize(initialW, initialH);
  renderer.shadowMap.enabled = true;
  renderer.shadowMap.type = PCFSoftShadowMap;
  args.mountEl.appendChild(renderer.domElement);
  renderer.domElement.setAttribute('role', 'img');
  renderer.domElement.setAttribute('aria-label', 'Living-room demo scene');
  renderer.domElement.tabIndex = 0;

  const scene = new Scene();
  scene.background = new Color(0x101820);

  const camera = new PerspectiveCamera(
    args.initialCamera.fov,
    initialW / Math.max(initialH, 1),
    0.05,
    100,
  );
  camera.position.set(...args.spec.camera.position);
  camera.lookAt(...args.spec.camera.lookAt);

  // ── orbit / look-around controls ────────────────────────────────
  // Drag to look around; wheel/pinch to zoom; right-drag to pan.
  // Constrains the camera to inside the room so the shopper can
  // never "fly through" the walls.
  let yaw = Math.atan2(
    args.spec.camera.lookAt[0] - args.spec.camera.position[0],
    args.spec.camera.lookAt[2] - args.spec.camera.position[2],
  );
  let pitch = 0;
  let isDragging = false;
  let lastX = 0;
  let lastY = 0;
  const updateCameraDir = (): void => {
    const px = args.spec.camera.position[0];
    const py = args.spec.camera.position[1];
    const pz = args.spec.camera.position[2];
    camera.position.set(px, py, pz);
    camera.lookAt(
      px + Math.sin(yaw) * Math.cos(pitch),
      py + Math.sin(pitch),
      pz + Math.cos(yaw) * Math.cos(pitch),
    );
  };
  updateCameraDir();
  renderer.domElement.style.touchAction = 'none';
  renderer.domElement.style.cursor = 'grab';
  renderer.domElement.addEventListener('pointerdown', (e) => {
    isDragging = true;
    lastX = e.clientX;
    lastY = e.clientY;
    renderer.domElement.style.cursor = 'grabbing';
    renderer.domElement.setPointerCapture(e.pointerId);
  });
  renderer.domElement.addEventListener('pointermove', (e) => {
    if (!isDragging) return;
    const dx = e.clientX - lastX;
    const dy = e.clientY - lastY;
    lastX = e.clientX;
    lastY = e.clientY;
    yaw -= dx * 0.005;
    pitch = Math.max(-1.2, Math.min(1.2, pitch - dy * 0.005));
    updateCameraDir();
  });
  const endDrag = (e: PointerEvent): void => {
    isDragging = false;
    renderer.domElement.style.cursor = 'grab';
    try {
      renderer.domElement.releasePointerCapture(e.pointerId);
    } catch {
      // ignore — capture may have been released already
    }
  };
  renderer.domElement.addEventListener('pointerup', endDrag);
  renderer.domElement.addEventListener('pointercancel', endDrag);

  // Resize handler — keep the renderer matched to the host element on
  // window resize / orientation change.
  const handleResize = (): void => {
    const w = args.mountEl.clientWidth || window.innerWidth;
    const h = args.mountEl.clientHeight || window.innerHeight;
    renderer.setSize(w, h);
    camera.aspect = w / Math.max(h, 1);
    camera.updateProjectionMatrix();
  };
  window.addEventListener('resize', handleResize);

  // Fill light so primitives are visible even before the day/night
  // controller wires in.
  const ambient = new AmbientLight(0xffffff, 0.55);
  scene.add(ambient);
  const sun = new DirectionalLight(0xfff2d8, 1.0);
  sun.position.set(3, 6, 2);
  sun.castShadow = true;
  scene.add(sun);

  // Build every primitive from the spec.
  let currentSpec = args.spec;
  const meshById = new Map<string, Mesh>();
  const lightById = new Map<string, PointLight>();
  for (const prim of args.spec.primitives) {
    addPrimitive(scene, prim, meshById, lightById, sun);
  }

  // Render loop — drives env updates + listens for the canvas to resize.
  let disposed = false;
  function frame(): void {
    if (disposed) return;
    renderer.render(scene, camera);
    requestAnimationFrame(frame);
  }
  requestAnimationFrame(frame);

  function applyMeshUpdate(prim: PrimitiveSpec): void {
    const mesh = meshById.get(prim.id);
    if (!mesh) return;
    if (prim.rotationDeg) {
      mesh.rotation.set(
        (prim.rotationDeg[0] * Math.PI) / 180,
        (prim.rotationDeg[1] * Math.PI) / 180,
        (prim.rotationDeg[2] * Math.PI) / 180,
      );
    }
    if (prim.scale) {
      mesh.scale.set(prim.scale[0], prim.scale[1], prim.scale[2]);
    }
    const material = mesh.material as MeshStandardMaterial;
    if (prim.color) material.color.setRGB(prim.color[0], prim.color[1], prim.color[2]);
    if (prim.emissive) {
      material.emissive.setRGB(prim.emissive[0], prim.emissive[1], prim.emissive[2]);
      material.emissiveIntensity = prim.emissive.some((c) => c > 0.01) ? 1.5 : 0;
    }
    if (prim.opacity !== undefined) {
      material.opacity = prim.opacity;
      material.transparent = prim.opacity < 1.0;
    }
    // Lamp twin → spawn/despawn a PointLight at the bulb position.
    if (prim.kind === 'sphere' && prim.emissive) {
      const lit = prim.emissive.some((c) => c > 0.01);
      const existing = lightById.get(prim.id);
      if (lit && !existing) {
        const light = new PointLight(0xfff2d8, 1.5, 6);
        light.position.set(prim.position[0], prim.position[1], prim.position[2]);
        light.castShadow = true;
        scene.add(light);
        lightById.set(prim.id, light);
      } else if (!lit && existing) {
        scene.remove(existing);
        existing.dispose();
        lightById.delete(prim.id);
      }
    }
  }

  return {
    setCamera(next): void {
      camera.fov = next.fov;
      camera.updateProjectionMatrix();
      args.onCameraChange?.(next);
    },

    updateTwinState(twinId, state): void {
      currentSpec = applyTwinStateToSpec(currentSpec, twinId, state);
      const target = currentSpec.primitives.find((p) => {
        const orig = findPrimitive(args.spec, p.id);
        // Only update if changed vs original spec or vs previous.
        return p.twinId === twinId || (orig && orig !== p);
      });
      if (target) applyMeshUpdate(target);
    },

    applyEnvironment(intensity, sunDir): void {
      ambient.intensity = 0.3 + intensity * 0.5;
      sun.intensity = intensity * 1.4;
      sun.position.set(sunDir[0] * 6, Math.max(sunDir[1], 0.05) * 6, sunDir[2] * 6);
    },

    currentSpec(): ProceduralRoomSpec {
      return currentSpec;
    },

    dispose(): void {
      disposed = true;
      window.removeEventListener('resize', handleResize);
      for (const mesh of meshById.values()) {
        scene.remove(mesh);
        mesh.geometry.dispose();
        (mesh.material as MeshStandardMaterial).dispose();
      }
      for (const light of lightById.values()) {
        scene.remove(light);
        light.dispose();
      }
      meshById.clear();
      lightById.clear();
      renderer.dispose();
      renderer.domElement.remove();
    },
  };
};

function addPrimitive(
  scene: Scene,
  prim: PrimitiveSpec,
  meshById: Map<string, Mesh>,
  lightById: Map<string, PointLight>,
  fallbackSun: DirectionalLight,
): void {
  if (prim.kind === 'directional-light') {
    fallbackSun.position.set(prim.position[0], prim.position[1], prim.position[2]);
    if (prim.color) {
      fallbackSun.color.setRGB(prim.color[0], prim.color[1], prim.color[2]);
    }
    return;
  }
  if (prim.kind === 'point-light') {
    const light = new PointLight(0xffffff, 1, 6);
    light.position.set(prim.position[0], prim.position[1], prim.position[2]);
    if (prim.color) light.color.setRGB(prim.color[0], prim.color[1], prim.color[2]);
    scene.add(light);
    lightById.set(prim.id, light);
    return;
  }
  const geometry =
    prim.kind === 'sphere'
      ? new SphereGeometry(prim.radius ?? 0.5, 24, 16)
      : prim.kind === 'cylinder'
        ? new CylinderGeometry(
            (prim.size?.[0] ?? 0.2) / 2,
            (prim.size?.[0] ?? 0.2) / 2,
            prim.size?.[1] ?? 1,
            24,
          )
        : prim.kind === 'plane'
          ? new PlaneGeometry(prim.size?.[0] ?? 1, prim.size?.[1] ?? 1)
          : new BoxGeometry(prim.size?.[0] ?? 1, prim.size?.[1] ?? 1, prim.size?.[2] ?? 1);
  const material = new MeshStandardMaterial({
    color: prim.color ? new Color(prim.color[0], prim.color[1], prim.color[2]) : 0xcccccc,
    emissive: prim.emissive
      ? new Color(prim.emissive[0], prim.emissive[1], prim.emissive[2])
      : 0x000000,
    emissiveIntensity: prim.emissive?.some((c) => c > 0.01) ? 1.5 : 0,
    roughness: 0.78,
    metalness: 0.04,
    transparent: prim.opacity !== undefined && prim.opacity < 1,
    opacity: prim.opacity ?? 1,
  });
  const mesh = new Mesh(geometry, material);
  mesh.position.set(prim.position[0], prim.position[1], prim.position[2]);
  if (prim.rotationDeg) {
    mesh.rotation.set(
      (prim.rotationDeg[0] * Math.PI) / 180,
      (prim.rotationDeg[1] * Math.PI) / 180,
      (prim.rotationDeg[2] * Math.PI) / 180,
    );
  }
  if (prim.scale) mesh.scale.set(prim.scale[0], prim.scale[1], prim.scale[2]);
  mesh.castShadow = prim.kind !== 'plane';
  mesh.receiveShadow = true;
  scene.add(mesh);
  meshById.set(prim.id, mesh);
}
