import {
  projectPoiToScreen,
  type CameraState,
  type SceneHotspot,
  type SceneNode,
} from '@nova/viewer-core';

/**
 * Hotspot overlay — DOM-projected teleport icons (F-10, F-11).
 *
 * Sister to the POI overlay (S14) but distinguished visually:
 *   - doorway → arrow glyph + larger pin
 *   - floor   → flat ring glyph (depth-nav)
 *   - teleport → backstep glyph
 *
 * Each hotspot is a `<button>` with `aria-label` + `aria-keyshortcuts` so screen
 * readers announce it. Click / Enter / Space → onTeleport callback.
 */

const KIND_GLYPH: Record<SceneHotspot['kind'], string> = {
  doorway: '↗',
  floor: '◯',
  teleport: '↻',
};

const KIND_LABEL_PREFIX: Record<SceneHotspot['kind'], string> = {
  doorway: 'Doorway',
  floor: 'Walkway',
  teleport: 'Teleport',
};

export interface HotspotOverlayArgs {
  hostEl: HTMLElement;
  scene: SceneNode;
  initialCamera: CameraState;
  onTeleport: (hotspot: SceneHotspot) => void;
}

export interface HotspotOverlayHandle {
  update(camera: CameraState): void;
  dispose(): void;
}

export const mountHotspotOverlay = (args: HotspotOverlayArgs): HotspotOverlayHandle => {
  const layer = document.createElement('div');
  layer.className = 'viewer-hotspot-layer';
  layer.setAttribute('data-testid', 'hotspot-overlay');
  args.hostEl.appendChild(layer);

  const pinByHotspotId = new Map<string, HTMLButtonElement>();
  const onClick =
    (hotspot: SceneHotspot) =>
    (event: MouseEvent): void => {
      event.preventDefault();
      args.onTeleport(hotspot);
    };

  for (const hotspot of args.scene.hotspots) {
    const pin = document.createElement('button');
    pin.type = 'button';
    pin.className = `viewer-hotspot viewer-hotspot--${hotspot.kind}`;
    pin.dataset.hotspotId = hotspot.id;
    pin.dataset.toScene = hotspot.toSceneId;
    pin.setAttribute('aria-label', `${KIND_LABEL_PREFIX[hotspot.kind]}: ${hotspot.label}`);
    pin.setAttribute('aria-keyshortcuts', 'Enter Space');
    pin.innerHTML = `<span class="viewer-hotspot-glyph" aria-hidden="true">${KIND_GLYPH[hotspot.kind]}</span>`;
    pin.addEventListener('click', onClick(hotspot));
    layer.appendChild(pin);
    pinByHotspotId.set(hotspot.id, pin);
  }

  const layout = (camera: CameraState): void => {
    const viewport = {
      widthPx: args.hostEl.clientWidth,
      heightPx: args.hostEl.clientHeight,
    };
    for (const hotspot of args.scene.hotspots) {
      const pin = pinByHotspotId.get(hotspot.id);
      if (pin === undefined) continue;
      const projection = projectPoiToScreen(
        { id: hotspot.id, yaw: hotspot.yawDeg, pitch: hotspot.pitchDeg },
        camera,
        viewport,
      );
      if (!projection.visible) {
        pin.hidden = true;
        continue;
      }
      pin.hidden = false;
      pin.style.transform = `translate(${projection.screenX.toFixed(1)}px, ${projection.screenY.toFixed(1)}px) translate(-50%, -50%)`;
    }
  };

  layout(args.initialCamera);

  return {
    update(camera): void {
      layout(camera);
    },
    dispose(): void {
      for (const pin of pinByHotspotId.values()) {
        pin.replaceWith();
      }
      pinByHotspotId.clear();
      if (layer.parentElement === args.hostEl) {
        args.hostEl.removeChild(layer);
      }
    },
  };
};
