import { FallbackSanitiser } from '@nova/viewer-core';

import { POI_TYPE_LABELS, type PoiTypeCode, type ViewerPoi } from './poi-types';

/**
 * Per-POI-type card-body renderer. Each fn returns an `HTMLElement` that
 * the overlay manager puts inside a shared `.poi-card` shell (title + close
 * button + content slot + footer).
 *
 * The contract is intentionally tiny:
 *   - never bind global listeners (only listeners on the returned element)
 *   - never reach outside the returned subtree
 *   - return a *new* element each call (no caching) — the overlay manager
 *     owns lifecycle + DOM removal
 *
 * Sanitisation: POI-08 HTML routes through `FallbackSanitiser`; production
 * may swap in DOMPurify behind the same `Sanitiser` interface (S39 hardening).
 */

const sanitiser = new FallbackSanitiser();

export interface PoiRenderContext {
  /** Active locale (e.g. 'en-US' / 'ar-KW'). Carded copy may localise. */
  locale: string;
  /** When true, the card should mirror inline icons for RTL. */
  isRtl: boolean;
  /** Callback when the visitor takes a CTA action (lead capture, click-through). */
  onCta?: (kind: string, payload: Record<string, unknown>) => void;
}

type CardRenderer = (poi: ViewerPoi, ctx: PoiRenderContext) => HTMLElement;

const div = (cls: string): HTMLDivElement => {
  const el = document.createElement('div');
  el.className = cls;
  return el;
};

const heading = (text: string): HTMLHeadingElement => {
  const h = document.createElement('h3');
  h.className = 'poi-card-title';
  h.textContent = text;
  return h;
};

const paragraph = (text: string): HTMLParagraphElement => {
  const p = document.createElement('p');
  p.textContent = text;
  return p;
};

const safeString = (raw: unknown): string => (typeof raw === 'string' ? raw : '');

const safeNumber = (raw: unknown): number | null =>
  typeof raw === 'number' && Number.isFinite(raw) ? raw : null;

const renderImage: CardRenderer = (poi) => {
  const root = div('poi-card-body poi-card-body--gallery');
  const images = (poi.payload.images as { url: string; alt?: string }[] | undefined) ?? [];
  if (safeString(poi.payload.title).length > 0) {
    root.appendChild(heading(safeString(poi.payload.title)));
  }
  const grid = div('poi-card-gallery');
  for (const img of images.slice(0, 12)) {
    const fig = document.createElement('figure');
    const el = document.createElement('img');
    el.src = img.url;
    el.alt = img.alt ?? '';
    el.loading = 'lazy';
    el.referrerPolicy = 'no-referrer';
    fig.appendChild(el);
    grid.appendChild(fig);
  }
  root.appendChild(grid);
  if (safeString(poi.payload.description).length > 0) {
    root.appendChild(paragraph(safeString(poi.payload.description)));
  }
  return root;
};

const renderVideo: CardRenderer = (poi) => {
  const root = div('poi-card-body poi-card-body--video');
  if (safeString(poi.payload.title).length > 0) {
    root.appendChild(heading(safeString(poi.payload.title)));
  }
  const v = document.createElement('video');
  v.src = safeString(poi.payload.videoUrl);
  v.controls = true;
  v.playsInline = true;
  v.preload = 'metadata';
  v.crossOrigin = 'anonymous';
  v.muted = poi.payload.muted !== false;
  if (poi.payload.loop === true) v.loop = true;
  const poster = safeString(poi.payload.posterUrl);
  if (poster.length > 0) v.poster = poster;
  root.appendChild(v);
  return root;
};

const render360Video: CardRenderer = (poi) => {
  const root = div('poi-card-body poi-card-body--video');
  root.appendChild(heading(safeString(poi.payload.title) || '360° video'));
  const note = paragraph('Tap to view this scene in 360°. Pinch to zoom; drag to pan.');
  note.className = 'poi-card-helper';
  root.appendChild(note);
  const v = document.createElement('video');
  v.src = safeString(poi.payload.videoUrl);
  v.controls = true;
  v.playsInline = true;
  v.preload = 'metadata';
  root.appendChild(v);
  return root;
};

const renderAudio: CardRenderer = (poi) => {
  const root = div('poi-card-body poi-card-body--audio');
  if (safeString(poi.payload.title).length > 0) {
    root.appendChild(heading(safeString(poi.payload.title)));
  }
  const a = document.createElement('audio');
  a.src = safeString(poi.payload.audioUrl);
  a.controls = true;
  a.preload = 'metadata';
  if (poi.payload.loop === true) a.loop = true;
  root.appendChild(a);
  if (poi.payload.spatial === true) {
    const hint = paragraph('Spatial audio — orient your device for best effect.');
    hint.className = 'poi-card-helper';
    root.appendChild(hint);
  }
  return root;
};

const renderIframe: CardRenderer = (poi) => {
  const root = div('poi-card-body poi-card-body--iframe');
  if (safeString(poi.payload.title).length > 0) {
    root.appendChild(heading(safeString(poi.payload.title)));
  }
  const f = document.createElement('iframe');
  f.src = safeString(poi.payload.src);
  f.referrerPolicy = 'no-referrer';
  // Default sandbox: no scripts, no top-navigation, no same-origin.
  // Tenants may opt in via manifest, but we never weaken below `allow-popups`.
  f.setAttribute('sandbox', safeString(poi.payload.sandbox) || 'allow-popups');
  f.loading = 'lazy';
  const w = safeNumber(poi.payload.width) ?? 800;
  const h = safeNumber(poi.payload.height) ?? 480;
  f.style.width = `${w}px`;
  f.style.height = `${h}px`;
  f.style.maxWidth = '100%';
  root.appendChild(f);
  return root;
};

const renderExternalLink: CardRenderer = (poi, ctx) => {
  const root = div('poi-card-body poi-card-body--link');
  if (safeString(poi.payload.title).length > 0) {
    root.appendChild(heading(safeString(poi.payload.title)));
  }
  if (safeString(poi.payload.description).length > 0) {
    root.appendChild(paragraph(safeString(poi.payload.description)));
  }
  const a = document.createElement('a');
  a.href = safeString(poi.payload.url);
  a.textContent = safeString(poi.payload.url);
  a.target = poi.payload.openInNewTab === false ? '_self' : '_blank';
  a.rel = 'noopener noreferrer';
  a.className = 'poi-card-cta';
  a.addEventListener('click', () => ctx.onCta?.('external_link', { url: a.href }));
  root.appendChild(a);
  return root;
};

const renderText: CardRenderer = (poi) => {
  const root = div('poi-card-body poi-card-body--text');
  if (safeString(poi.payload.title).length > 0) {
    root.appendChild(heading(safeString(poi.payload.title)));
  }
  const p = document.createElement('p');
  p.textContent = safeString(poi.payload.body);
  p.style.whiteSpace = 'pre-wrap';
  root.appendChild(p);
  return root;
};

const renderHtml: CardRenderer = (poi) => {
  const root = div('poi-card-body poi-card-body--html');
  if (safeString(poi.payload.title).length > 0) {
    root.appendChild(heading(safeString(poi.payload.title)));
  }
  const wrap = div('poi-card-html');
  wrap.innerHTML = sanitiser.sanitize(safeString(poi.payload.html));
  root.appendChild(wrap);
  return root;
};

const formatBytes = (n: number): string => {
  if (n < 1024) return `${n} B`;
  if (n < 1024 * 1024) return `${(n / 1024).toFixed(1)} KB`;
  if (n < 1024 * 1024 * 1024) return `${(n / (1024 * 1024)).toFixed(1)} MB`;
  return `${(n / (1024 * 1024 * 1024)).toFixed(2)} GB`;
};

const renderDownload: CardRenderer = (poi, ctx) => {
  const root = div('poi-card-body poi-card-body--download');
  if (safeString(poi.payload.title).length > 0) {
    root.appendChild(heading(safeString(poi.payload.title)));
  }
  const a = document.createElement('a');
  a.href = safeString(poi.payload.fileUrl);
  a.download = safeString(poi.payload.fileName) || 'download.bin';
  a.className = 'poi-card-cta';
  const sizeMeta = safeNumber(poi.payload.sizeBytes);
  const sizeStr = sizeMeta === null ? '' : ` · ${formatBytes(sizeMeta)}`;
  a.textContent = `Download ${a.download}${sizeStr}`;
  a.addEventListener('click', () => ctx.onCta?.('download', { fileName: a.download }));
  root.appendChild(a);
  return root;
};

const renderPdf: CardRenderer = (poi) => {
  const root = div('poi-card-body poi-card-body--pdf');
  if (safeString(poi.payload.title).length > 0) {
    root.appendChild(heading(safeString(poi.payload.title)));
  }
  const obj = document.createElement('object');
  obj.data = safeString(poi.payload.pdfUrl);
  obj.type = 'application/pdf';
  obj.style.width = '100%';
  obj.style.height = '60vh';
  const fallback = document.createElement('a');
  fallback.href = obj.data;
  fallback.target = '_blank';
  fallback.rel = 'noopener noreferrer';
  fallback.textContent = 'Open PDF in a new tab';
  obj.appendChild(fallback);
  root.appendChild(obj);
  return root;
};

const renderForm: CardRenderer = (poi, ctx) => {
  const root = div('poi-card-body poi-card-body--form');
  if (safeString(poi.payload.title).length > 0) {
    root.appendChild(heading(safeString(poi.payload.title)));
  }
  const form = document.createElement('form');
  form.className = 'poi-card-form';
  form.setAttribute('data-form-id', safeString(poi.payload.formId));
  // Default lead-capture shape: name + email + message. The dashboard
  // (S22) lets tenants compose richer forms; for now we ship the
  // most-requested baseline so the panorama path doesn't block on a
  // form builder UI.
  const fields: { label: string; type: string; name: string; required?: boolean }[] = [
    { label: 'Name', type: 'text', name: 'name', required: true },
    { label: 'Email', type: 'email', name: 'email', required: true },
    { label: 'Message', type: 'textarea', name: 'message' },
  ];
  for (const field of fields) {
    const labelEl = document.createElement('label');
    labelEl.className = 'poi-form-row';
    const span = document.createElement('span');
    span.textContent = field.label;
    labelEl.appendChild(span);
    const input =
      field.type === 'textarea'
        ? document.createElement('textarea')
        : document.createElement('input');
    if (input instanceof HTMLInputElement) input.type = field.type;
    input.name = field.name;
    if (field.required === true) input.required = true;
    if (input instanceof HTMLTextAreaElement) input.rows = 4;
    labelEl.appendChild(input);
    form.appendChild(labelEl);
  }
  const submit = document.createElement('button');
  submit.type = 'submit';
  submit.className = 'poi-card-cta';
  submit.textContent = 'Submit';
  form.appendChild(submit);
  form.addEventListener('submit', (event) => {
    event.preventDefault();
    const fd = new FormData(form);
    const payload: Record<string, unknown> = {};
    fd.forEach((value, key) => {
      payload[key] = value;
    });
    payload.formId = safeString(poi.payload.formId);
    ctx.onCta?.('form_submit', payload);
    submit.disabled = true;
    submit.textContent = 'Thanks — submitted';
  });
  root.appendChild(form);
  return root;
};

const renderObject3d: CardRenderer = (poi) => {
  const root = div('poi-card-body poi-card-body--object3d');
  if (safeString(poi.payload.title).length > 0) {
    root.appendChild(heading(safeString(poi.payload.title)));
  }
  // Lightweight stub: shows a placeholder + a download link. The actual
  // GLB viewer (separate Three.js scene with orbit controls) lands when
  // the dashboard product team ships the "view 3D model" interaction
  // in S15.
  const placeholder = div('poi-card-3d-placeholder');
  placeholder.textContent = '3D model';
  placeholder.setAttribute('aria-label', '3D model preview placeholder');
  root.appendChild(placeholder);
  const a = document.createElement('a');
  a.href = safeString(poi.payload.glbUrl);
  a.textContent = 'Download GLB';
  a.className = 'poi-card-cta';
  a.rel = 'noopener noreferrer';
  root.appendChild(a);
  return root;
};

const renderPointCloud: CardRenderer = (poi) => {
  const root = div('poi-card-body poi-card-body--splat');
  if (safeString(poi.payload.title).length > 0) {
    root.appendChild(heading(safeString(poi.payload.title)));
  }
  const note = paragraph('Gaussian Splat preview — opens in the dedicated splat viewer (Block H).');
  note.className = 'poi-card-helper';
  root.appendChild(note);
  const a = document.createElement('a');
  a.href = safeString(poi.payload.splatUrl);
  a.textContent = 'Open splat';
  a.className = 'poi-card-cta';
  a.target = '_blank';
  a.rel = 'noopener noreferrer';
  root.appendChild(a);
  return root;
};

const formatCurrency = (priceMinor: number, currency: string, locale: string): string => {
  try {
    return new Intl.NumberFormat(locale, {
      style: 'currency',
      currency,
    }).format(priceMinor / 100);
  } catch {
    return `${(priceMinor / 100).toFixed(2)} ${currency}`;
  }
};

const renderProductCard: CardRenderer = (poi, ctx) => {
  const root = div('poi-card-body poi-card-body--product');
  if (safeString(poi.payload.title).length > 0) {
    root.appendChild(heading(safeString(poi.payload.title)));
  }
  // Hero media: a per-product video if supplied (the lamp's clip, the TV's
  // clip …) else the product image.
  const videoUrl = safeString(poi.payload.videoUrl);
  const imageUrl = safeString(poi.payload.imageUrl);
  if (videoUrl.length > 0) {
    const v = document.createElement('video');
    v.src = videoUrl;
    v.controls = true;
    v.playsInline = true;
    v.muted = true;
    v.preload = 'metadata';
    if (imageUrl.length > 0) v.poster = imageUrl;
    v.className = 'poi-card-product-video';
    root.appendChild(v);
  } else if (imageUrl.length > 0) {
    const img = document.createElement('img');
    img.src = imageUrl;
    img.alt = safeString(poi.payload.title) || 'Product';
    img.loading = 'lazy';
    img.className = 'poi-card-product-img';
    root.appendChild(img);
  }
  const meta = div('poi-card-product-meta');
  const priceMinor = safeNumber(poi.payload.priceMinor) ?? 0;
  const currency = safeString(poi.payload.currency) || 'USD';
  const price = document.createElement('strong');
  price.className = 'poi-card-product-price';
  price.textContent = formatCurrency(priceMinor, currency, ctx.locale);
  meta.appendChild(price);

  const inv = safeString(poi.payload.inventoryHint);
  if (inv.length > 0) {
    const badge = document.createElement('span');
    badge.className = `poi-card-badge poi-card-badge--${inv.toLowerCase().replace('_', '-')}`;
    badge.textContent = inv.replace('_', ' ').toLowerCase();
    meta.appendChild(badge);
  }
  root.appendChild(meta);

  const description = safeString(poi.payload.description);
  if (description.length > 0) {
    root.appendChild(paragraph(description));
  }

  // Specs list — payload.specs is an array of { label, value } (or strings).
  const specs = poi.payload.specs;
  if (Array.isArray(specs) && specs.length > 0) {
    const ul = document.createElement('ul');
    ul.className = 'poi-card-product-specs';
    for (const s of specs) {
      const li = document.createElement('li');
      if (s && typeof s === 'object' && 'label' in (s as Record<string, unknown>)) {
        const labelEl = document.createElement('span');
        labelEl.className = 'spec-label';
        labelEl.textContent = safeString((s as Record<string, unknown>).label);
        const valueEl = document.createElement('span');
        valueEl.className = 'spec-value';
        valueEl.textContent = safeString((s as Record<string, unknown>).value);
        li.append(labelEl, valueEl);
      } else {
        li.textContent = safeString(s);
      }
      ul.appendChild(li);
    }
    root.appendChild(ul);
  }

  const sku = safeString(poi.payload.productSku);
  if (sku.length > 0) {
    const small = document.createElement('small');
    small.className = 'poi-card-product-sku';
    small.textContent = `SKU ${sku}`;
    root.appendChild(small);
  }

  const cta = document.createElement('button');
  cta.type = 'button';
  cta.className = 'poi-card-cta';
  cta.textContent = 'Add to cart';
  cta.addEventListener('click', () => ctx.onCta?.('add_to_cart', { sku, priceMinor, currency }));
  root.appendChild(cta);
  return root;
};

const renderVideoHotspot: CardRenderer = (poi) => {
  const root = div('poi-card-body poi-card-body--video');
  if (safeString(poi.payload.title).length > 0) {
    root.appendChild(heading(safeString(poi.payload.title)));
  }
  const v = document.createElement('video');
  v.src = safeString(poi.payload.videoUrl);
  v.controls = true;
  v.playsInline = true;
  v.preload = 'metadata';
  root.appendChild(v);
  const triggers =
    (poi.payload.triggers as
      | { atSeconds: number; actionLabel: string; actionUrl?: string }[]
      | undefined) ?? [];
  if (triggers.length > 0) {
    const list = document.createElement('ol');
    list.className = 'poi-card-video-triggers';
    for (const t of triggers) {
      const li = document.createElement('li');
      li.textContent = `${formatTimestamp(t.atSeconds)} · ${t.actionLabel}`;
      if (safeString(t.actionUrl).length > 0) {
        const a = document.createElement('a');
        a.href = safeString(t.actionUrl);
        a.target = '_blank';
        a.rel = 'noopener noreferrer';
        a.textContent = ' →';
        li.appendChild(a);
      }
      list.appendChild(li);
    }
    root.appendChild(list);
  }
  return root;
};

const formatTimestamp = (seconds: number): string => {
  const m = Math.floor(seconds / 60);
  const s = Math.floor(seconds % 60)
    .toString()
    .padStart(2, '0');
  return `${m}:${s}`;
};

export const POI_CARD_RENDERERS: Record<PoiTypeCode, CardRenderer> = {
  'POI-01': renderImage,
  'POI-02': renderVideo,
  'POI-03': render360Video,
  'POI-04': renderAudio,
  'POI-05': renderIframe,
  'POI-06': renderExternalLink,
  'POI-07': renderText,
  'POI-08': renderHtml,
  'POI-09': renderDownload,
  'POI-10': renderPdf,
  'POI-11': renderForm,
  'POI-12': renderObject3d,
  'POI-13': renderPointCloud,
  'POI-14': renderProductCard,
  'POI-15': renderVideoHotspot,
  'POI-16': renderImage,
};

export const renderUnknownPoiCard = (poi: ViewerPoi): HTMLElement => {
  const root = div('poi-card-body poi-card-body--unknown');
  root.appendChild(heading('Unsupported POI'));
  root.appendChild(
    paragraph(
      `This panorama uses POI type ${poi.typeCode} (${POI_TYPE_LABELS[poi.typeCode] ?? 'unknown'}) which this viewer build does not render. Update the viewer to see it.`,
    ),
  );
  return root;
};
