/**
 * Procedural room — pure-data Three.js scene specification.
 *
 * Describes a furnished demo living room composed entirely of
 * primitive meshes (box / sphere / plane / cylinder). The viewer's
 * Three.js adapter consumes this spec to build the actual scene
 * graph; the spec itself is GPU-free + framework-free so we can
 * test every twin binding without WebGL.
 *
 * Visitor toggles via `@nova/digital-twin` flip the spec's twin
 * states; the adapter listens for state changes and updates the
 * matching primitive's transform / material in real time:
 *
 *   - lamp twin → spawns/despawns a PointLight at the bulb's pose
 *     + flips an `emissive` colour on the bulb material.
 *   - door twin → tweens the door box's `rotation.y` by 90°.
 *   - curtain (shade) twin → tweens the curtain plane's
 *     `scale.x` from 1 (closed) to 0 (open).
 *   - TV (media-display) twin → swaps the screen plane material
 *     between `'#000000'` (off) and an emissive `'#4dd2ff'` (on).
 *   - faucet (custom) → spawns a translucent water cylinder.
 *   - window (custom) → rotates the pane primitive.
 *
 * Every primitive has a stable id so the renderer adapter can
 * look it up + the scene-state controller can target it. The spec
 * also carries the twin-binding metadata the `@nova/digital-twin`
 * registry needs to surface visitor-tap chips.
 */

import type { Twin } from '@nova/digital-twin';

export type Vec3 = readonly [number, number, number];
export type Rgb = readonly [number, number, number];

export type PrimitiveKind =
  | 'box'
  | 'sphere'
  | 'plane'
  | 'cylinder'
  | 'point-light'
  | 'directional-light';

export interface PrimitiveSpec {
  readonly id: string;
  readonly kind: PrimitiveKind;
  readonly position: Vec3;
  readonly rotationDeg?: Vec3;
  readonly scale?: Vec3;
  /** Box / cylinder dimensions (metres). Spheres use `radius`. */
  readonly size?: Vec3;
  readonly radius?: number;
  readonly color?: Rgb;
  /** Emissive colour for lit / on-state. */
  readonly emissive?: Rgb;
  /** 0..1 — when set, material is transparent. */
  readonly opacity?: number;
  /** Optional Twin id this primitive responds to.
   *  Drives the runtime adapter's state-change handler. */
  readonly twinId?: string;
}

export interface ProceduralRoomSpec {
  readonly sceneId: string;
  readonly primitives: readonly PrimitiveSpec[];
  /** Twins to register alongside the spec. */
  readonly twins: readonly Twin[];
  /** Camera starting pose (head position + look direction). */
  readonly camera: { readonly position: Vec3; readonly lookAt: Vec3 };
}

