/** Look up a primitive by id (typed helper). */
export function findPrimitive(spec: ProceduralRoomSpec, id: string): PrimitiveSpec | undefined {
  return spec.primitives.find((p) => p.id === id);
}

/** Look up the primitive bound to a given twin id (one-to-one for our twins). */
export function findPrimitiveForTwin(
  spec: ProceduralRoomSpec,
  twinId: string,
): PrimitiveSpec | undefined {
  return spec.primitives.find((p) => p.twinId === twinId);
}

/** Visitor-toggleable twin ids (for quick capability filtering). */
export function interactiveTwinIds(spec: ProceduralRoomSpec): readonly string[] {
  return spec.twins.map((t) => t.id);
}
