import { buildSceneGraph, type SceneGraph, type SceneNode } from '@nova/viewer-core';

/**
 * Demo tour for the viewer bootstrap until the dashboard wires the real
 * tour-svc + media-svc handshake (S22). 4 scenes: lobby → corridor →
 * showroom → balcony, plus a "Lobby — Night" variant for F-17.
 *
 * All scenes intentionally share the same panorama URL because:
 *   - dev: we only ship one fixture (apps/viewer/public/fixtures/test-panorama.jpg)
 *   - prod demo: a CDN URL is provided per scene via `?panorama=` override
 *
 * The point of the demo is to exercise the navigation mechanics (hotspot
 * teleport, minimap jump, variant switch, history back/forward) — visual
 * content is identical so reviewers can focus on chrome differences.
 */

const FIXTURE = '/fixtures/test-panorama.jpg';

const QUERY_PANORAMA =
  typeof location !== 'undefined' ? new URLSearchParams(location.search).get('panorama') : null;

const fixture = QUERY_PANORAMA ?? FIXTURE;

const lobby: SceneNode = {
  id: 'lobby',
  name: 'Lobby',
  defaultPanoramaUrl: fixture,
  defaultYawDeg: 0,
  defaultPitchDeg: 0,
  defaultFovDeg: 75,
  minimapAnchor: { x: 0.18, y: 0.5 },
  variants: [
    { id: 'day', label: 'Day', panoramaUrl: fixture },
    { id: 'night', label: 'Night', panoramaUrl: fixture },
  ],
  hotspots: [
    {
      id: 'lobby-to-corridor',
      toSceneId: 'corridor',
      yawDeg: 30,
      pitchDeg: -8,
      arriveYawDeg: 270,
      arrivePitchDeg: 0,
      kind: 'doorway',
      label: 'Step into the corridor',
      transition: 'fade',
    },
    {
      id: 'lobby-to-balcony',
      toSceneId: 'balcony',
      yawDeg: -55,
      pitchDeg: -4,
      kind: 'floor',
      label: 'Walk onto the balcony',
      transition: 'fade',
    },
  ],
};

const corridor: SceneNode = {
  id: 'corridor',
  name: 'Corridor',
  defaultPanoramaUrl: fixture,
  defaultYawDeg: 90,
  defaultPitchDeg: 0,
  minimapAnchor: { x: 0.42, y: 0.5 },
  hotspots: [
    {
      id: 'corridor-to-lobby',
      toSceneId: 'lobby',
      yawDeg: 200,
      pitchDeg: -6,
      kind: 'doorway',
      label: 'Back to lobby',
      transition: 'fade',
    },
    {
      id: 'corridor-to-showroom',
      toSceneId: 'showroom',
      yawDeg: 15,
      pitchDeg: -4,
      kind: 'doorway',
      label: 'Continue to the showroom',
      transition: 'fade',
    },
  ],
};

const showroom: SceneNode = {
  id: 'showroom',
  name: 'Showroom',
  defaultPanoramaUrl: fixture,
  defaultYawDeg: 0,
  defaultPitchDeg: 0,
  minimapAnchor: { x: 0.7, y: 0.5 },
  hotspots: [
    {
      id: 'showroom-to-corridor',
      toSceneId: 'corridor',
      yawDeg: 180,
      pitchDeg: -8,
      kind: 'doorway',
      label: 'Back to corridor',
      transition: 'fade',
    },
  ],
};

const balcony: SceneNode = {
  id: 'balcony',
  name: 'Balcony',
  defaultPanoramaUrl: fixture,
  defaultYawDeg: 180,
  defaultPitchDeg: -5,
  minimapAnchor: { x: 0.18, y: 0.82 },
  hotspots: [
    {
      id: 'balcony-to-lobby',
      toSceneId: 'lobby',
      yawDeg: 0,
      pitchDeg: -10,
      kind: 'doorway',
      label: 'Back inside',
      transition: 'fade',
    },
  ],
};

export const DEMO_SCENE_GRAPH: SceneGraph = buildSceneGraph({
  scenes: [lobby, corridor, showroom, balcony],
  rootSceneId: 'lobby',
  minimapViewBox: { widthPx: 200, heightPx: 200 },
});
